  const live = isJobLive(job);

  useEffect(() => {
    if (!live) return;
    const id = window.setInterval(() => setNow(Date.now()), 100);
    return () => window.clearInterval(id);
  }, [live]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [job?.steps.length]);

  if (!job) return null;
  const model = MODEL_BY_ID[job.model];
  const elapsed = (((job.finishedAt ?? now) - job.startedAt) / 1000).toFixed(1);
  const route = jobRouteLabel(job);
  const rgb = getGame(job.gameId)?.rgb ?? model.rgb;

  if (!live) {
    const ok = job.status === "done";
    return (
      <div className="cy5-glass animate-rise mb-2.5 flex items-center gap-3 rounded-2xl px-3.5 py-2.5 tint" style={{ ["--c" as string]: rgb }}>
        <span
          className="grid h-7 w-7 shrink-0 place-items-center rounded-lg text-[13px]"
          style={{ background: ok ? `rgb(${rgb} / 0.16)` : "rgb(244 63 94 / 0.14)", color: ok ? "var(--cc)" : "#f43f5e" }}
        >
          {ok ? <CheckIcon /> : <CloseIcon />}
        </span>
        <div className="min-w-0 flex-1 text-[12.5px]">
          <div className="truncate font-medium text-cy-ink">
            {ok ? (
              <>
                Forged <span style={{ color: "var(--cc-ink)" }}>{job.modName}</span> v{job.version}
              </>
            ) : job.status === "cancelled" ? (
              job.real ? "Build stopped" : "Forge stopped"
            ) : job.real ? (
              "Didn't build"
            ) : (
              "Forge failed"
            )}
          </div>
          <div className="truncate text-[11px] text-cy-muted">
            {ok ? `${job.files.length} files · ${route} · ${model.name} · ${elapsed}s` : (job.error ?? (job.real ? "Tokens a build didn't use go back to you." : "Nothing was saved."))}
          </div>
          {job.real && job.buildId && <div className="truncate"><BuildSpendLine buildId={job.buildId} /></div>}
        </div>
        {ok && (
          <button type="button" onClick={() => setPanelTab("code")} className="cy5-btn-ghost h-8 px-2.5 text-[12px]">
            <CodeIcon /> View code
          </button>
        )}
        <button type="button" aria-label="Dismiss" onClick={() => useStore.setState({ job: null })} className="cy5-btn-ghost h-8 w-8 text-cy-muted">
          <CloseIcon />
        </button>
      </div>
    );
  }

  return (
    <div className="cy5-glass animate-rise hairline-top mb-2.5 overflow-hidden rounded-2xl">
      <button type="button" onClick={() => setOpen((o) => !o)} className="flex w-full items-center gap-3 px-3.5 py-2.5 text-left">
        <span className="think-badge" aria-hidden>
          <ThinkingBrain />
        </span>
        <div className="min-w-0 flex-1">
          <div className="shimmer-text font-cy-display text-[13px] font-semibold">
            {job.status === "writing" ? "Cyrus is writing code" : job.status === "connecting" ? "Waking the core" : "Cyrus is thinking"}
          </div>
          <div className="truncate text-[11px] text-cy-muted">{route ? `Cyrus Core › ${route}` :"Routing your idea through the network…"}</div>
        </div>
        <span className="tint flex items-center gap-1.5 rounded-lg px-2 py-1 text-[11px] text-cy-ink-2" style={{ ["--c" as string]: model.rgb, background: `rgb(${model.rgb} / 0.1)` }}>
          <ModelGlyph id={model.id} size={15} />
          {model.name}
        </span>
        {job.real && job.credits > 0 && (
          <span className="hidden items-center gap-1 text-[11px] tabular-nums text-cy-muted sm:inline-flex" title="Tokens held while this build runs. It only spends what it uses.">
            <CoinSpin size={16} /> {job.credits.toLocaleString("en-US")} held
          </span>
        )}
        <span className="w-11 text-right font-mono text-[11px] tabular-nums text-cy-muted">{elapsed}s</span>
        <ChevronDownIcon className={`text-cy-muted transition ${open ? "" : "-rotate-90"}`} />
      </button>
      <div className="relative h-[2px] overflow-hidden bg-[rgb(var(--glow)/0.08)]">
        <div className="absolute inset-y-0 w-1/3 bg-gradient-to-r from-transparent via-cy-cyan to-transparent" style={{ animation: "cy5-progress-sheen 1.3s ease-in-out infinite" }} />
      </div>
      {job.real && job.buildId && <LiveSpendMeter buildId={job.buildId} live />}
      {open && (
        <ul
          ref={listRef}
          className="max-h-[188px] overflow-y-auto px-3.5 py-2"
          style={{ maskImage: "linear-gradient(180deg, transparent 0, #000 14px, #000 100%)" }}
        >
          {job.steps.map((s, i) => (
            <StepRow key={s.id} s={s} job={job} last={i === job.steps.length - 1} />
          ))}
          {job.steps.length === 0 && (
            <li className="flex items-center gap-2.5 py-1.5 text-[12.5px]">
              <Spinner />
              <span className="shimmer-text">Opening a channel to the core…</span>
            </li>
          )}
        </ul>
      )}
    </div>
  );
}
