const ENABLED = (env = process.env) => env.CYRUS_LIVE_ASSETS === "1";

const KINDS = [
  { kind: "texture", re: /^assets\/textures\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "sound", re: /^assets\/sounds\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "datapack", re: /^assets\/datapack\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "design", re: /^assets\/designs\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "creature", re: /^assets\/creatures\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "itemmodel", re: /^assets\/itemmodels\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "config", re: /^assets\/config\/schema\.json$/ },
  { kind: "library", re: /^assets\/library\.json$/ },
];
const ASSET_KINDS = KINDS.map((k) => k.kind);

const MAX_SPEC_BYTES = 64 * 1024; // the largest service cap is 48 KB (RigSpec); anything bigger is never shown
const MAX_EVENTS = 240; // ring kept in memory while the build runs
const MAX_STORED_EVENTS = 160; // replay timeline kept after the build
const MAX_STORED_BYTES = 384 * 1024;
const MAX_INFO = 12;

/** Workspace-relative asset path -> kind, or null (never anything outside the asset folders). */
function kindOfPath(rel) {
  if (typeof rel !== "string" || rel.length > 120 || rel.includes("..") || rel.includes("\\")) return null;
  for (const k of KINDS) if (k.re.test(rel)) return k.kind;
  return null;
}
/** A tool's file_path (absolute or relative) -> {rel, kind} inside `ws`, or null. */
function assetRel(ws, fp) {
  if (!fp || typeof fp !== "string") return null;
  const abs = path.resolve(ws, fp);
  if (abs !== ws && !abs.startsWith(ws + path.sep)) return null;
  const rel = path.posix.normalize(path.relative(ws, abs).split(path.sep).join("/"));
  const kind = kindOfPath(rel);
