/** A finished Write/Edit of a spec (content is the file as it is on disk now, already secret-checked by the caller). */
function complete(log, rel, kind, content, op) {
  if (typeof content !== "string") return null;
  const bytes = Buffer.byteLength(content, "utf8");
  if (bytes > MAX_SPEC_BYTES) return push(log, { type: "complete", kind, path: rel, op, bytes, truncated: true });
  return push(log, { type: "complete", kind, path: rel, op, bytes, content });
}
/** Validator verdicts for one asset round, from the per-kind check results ({rel, name, ok, problems}). */
function verdicts(log, kind, results, { final } = {}) {
  if (!log || !Array.isArray(results)) return;
  for (const r of results.slice(0, 32)) {
    if (!r || !kindOfPath(r.rel)) continue;
    if (r.ok) push(log, { type: "validated", kind, path: r.rel, name: clip(r.name, 40), ...(r.sha256 ? { sha256: clip(r.sha256, 64) } : {}) });
