/** Library picks accepted by the service (refs are the offered pool's; titles come from the gated pool). */
function picks(log, slots, pool) {
  if (!log || !Array.isArray(slots) || !slots.length) return;
  const byRef = new Map((pool || []).map((p) => [p.ref, p]));
  const info = slots.slice(0, MAX_INFO).map((s) => {
    const row = (byRef.get(s.libraryRef) || {}).row || {};
    const title = typeof row.title === "string" ? row.title : typeof row.name === "string" ? row.name : null;
    return { id: clip(s.id, 48), kind: clip(s.kind, 12), purpose: clip(s.purpose, 160), ...(title ? { title: clip(title, 80) } : {}) };
