    // drop the oldest content first (its later complete/validated rows stay), then whole rows
    const i = evs.findIndex((e) => typeof e.content === "string");
    if (i >= 0) { const { content, ...rest } = evs[i]; void content; evs[i] = { ...rest, truncated: true }; }
