/** The draft (tool input still streaming) as an asset draft, or null. `partialField` is live.js's decoder. */
function draftOf(ws, d, partialField, want, wantSeq, wantFrom) {
  if (!d || !d.json) return null;
  const fp = partialField(d.json, "file_path");
  const a = fp && fp.done ? assetRel(ws, fp.text) : null;
  if (!a) return null;
  // An Edit's new_string is a fragment, not the spec: only Writes stream; Edits arrive as `complete`.
  if (d.tool !== "Write") return { kind: a.kind, path: a.rel, op: "edit", seq: d.seq, from: 0, text: "", total: 0, done: !!d.done };
  const field = partialField(d.json, "content");
  const text = field ? field.text : "";
  if (Buffer.byteLength(text, "utf8") > MAX_SPEC_BYTES) return { kind: a.kind, path: a.rel, op: "write", seq: d.seq, from: 0, text: "", total: text.length, done: !!d.done, truncated: true };
  const from = want === a.rel && wantSeq === d.seq ? Math.max(0, Math.min(text.length, wantFrom || 0)) : 0;
  return { kind: a.kind, path: a.rel, op: "write", seq: d.seq, from, text: text.slice(from), total: text.length, done: !!d.done || !!(field && field.done) };
}

module.exports = { ENABLED, KINDS, ASSET_KINDS, MAX_SPEC_BYTES, MAX_EVENTS, MAX_STORED_EVENTS, MAX_STORED_BYTES, kindOfPath, assetRel, newLog, push, complete, verdicts, picks, built, shippedOf, since, stored, draftOf };

