import { MOTION_PRESETS, presetById } from "../../motion/presets";
import { Key, NsRef, Text, VanillaRef, type DzIssue } from "../spec";
import { lowerMinecraft, type McProgram } from "./lower";
const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");

/** The MotionSpec a design stands for (the preset built with its params, or the inline spec parsed). */
export function resolveMotion(d: MotionDesign): { spec: MotionSpec | null; errors: DzIssue[]; warnings: DzIssue[] } {
  const m = d.motion as { preset?: unknown; params?: Record<string, unknown> } | unknown;
  if (m && typeof m === "object" && typeof (m as { preset?: unknown }).preset === "string") {
    const id = (m as { preset: string }).preset;
    const p = presetById(id);
    if (!p) return { spec: null, errors: [{ path: "motion.preset", code: "unknown_preset", message: `no motion preset ${id}; use one of ${MOTION_PRESETS.map((x) => x.id).join(", ")}` }], warnings: [] };
    const b = p.build((m as { params?: Record<string, unknown> }).params ?? {});
    return { spec: { ...b.spec, id: d.id }, errors: [], warnings: b.issues.map((i) => ({ path: `motion.params.${i.param}`, code: "param_clamped", message: i.message })) };
  }
  const s = MotionSpecSchema.safeParse(m);
  if (!s.success) return { spec: null, errors: s.error.issues.slice(0, 20).map((i) => ({ path: `motion.${issuePath(i.path)}`.replace(/\.$/, ""), code: "schema", message: i.message })), warnings: [] };
  if (s.data.id !== d.id) return { spec: null, errors: [{ path: "motion.id", code: "id_mismatch", message: `motion.id "${s.data.id}" must equal the design id "${d.id}"` }], warnings: [] };
  return { spec: s.data, errors: [], warnings: [] };
}

export function validateMotionDesign(input: unknown, ctx: MotionDesignContext): MotionDesignValidation {
  const errors: DzIssue[] = [];
  const warnings: DzIssue[] = [];
  let bytes = Infinity;
  try { bytes = new TextEncoder().encode(JSON.stringify(input)).length; } catch { /* not JSON */ }
  if (bytes > MOTION_DESIGN_LIMITS.maxSpecBytes) return { ok: false, errors: [{ path: "(root)", code: "spec_size", message: `the motion design is ${bytes} bytes; the limit is ${MOTION_DESIGN_LIMITS.maxSpecBytes}` }], warnings, dropped: [] };
  const p = MotionDesignSchema.safeParse(input);
  if (!p.success) return { ok: false, errors: p.error.issues.slice(0, 30).map((i) => ({ path: issuePath(i.path) || "(root)", code: "schema", message: i.message })), warnings, dropped: [] };
  const d = p.data;
  const r = resolveMotion(d);
  warnings.push(...r.warnings);
  if (!r.spec) return { ok: false, errors: r.errors, warnings, dropped: [] };
  // part bindings: vanilla ids for this version, models in this mod
  for (const [node, b] of Object.entries(d.minecraft?.parts ?? {})) {
    const at = `minecraft.parts.${node}`;
    if ("block" in b) { if (!isVanilla("block", b.block, ctx.version)) errors.push({ path: `${at}.block`, code: "unknown_vanilla_id", message: missingIdReason("block", b.block, ctx.version) }); }
    else {
      if (!isVanilla("item", b.item, ctx.version)) errors.push({ path: `${at}.item`, code: "unknown_vanilla_id", message: missingIdReason("item", b.item, ctx.version) });
      if (b.model && ctx.assets?.models && !ctx.assets.models.includes(b.model)) warnings.push({ path: `${at}.model`, code: "asset_unresolved", message: `${b.model}: this mod has no such item model; the part shows the plain ${b.item}` });
    }
  }
  // sound keys of this mod (only checked when known)
  for (const c of r.spec.clips) for (const t of c.tracks) if (t.kind === "sound" && t.sound.startsWith(`${ctx.namespace}:`) && ctx.assets?.sounds && !ctx.assets.sounds.includes(t.sound)) warnings.push({ path: `motion.clips.${c.name}`, code: "asset_unresolved", message: `${t.sound}: this mod has no such custom sound, so it plays nothing` });
  const parts: Record<string, { block?: string; item?: string; model?: string }> = {};
  for (const [k, b] of Object.entries(d.minecraft?.parts ?? {})) parts[k] = "block" in b ? { block: b.block } : { item: b.item, ...(b.model && (!ctx.assets?.models || ctx.assets.models.includes(b.model)) ? { model: b.model } : {}) };
  const lo = lowerMinecraft(r.spec, { parts, triggers: d.minecraft?.triggers }, { namespace: ctx.namespace, sounds: ctx.assets?.soundsById });
  const conv = (i: { path: string; code: string; message: string }) => ({ path: i.path.startsWith("minecraft.") ? i.path : `motion.${i.path}`, code: i.code, message: i.message });
  warnings.push(...lo.warnings.map(conv));
  if (!lo.ok) return { ok: false, errors: [...errors, ...lo.errors.map(conv)], warnings, dropped: lo.dropped };
  if (errors.length) return { ok: false, errors, warnings, dropped: lo.dropped };
  for (const x of lo.dropped) warnings.push({ path: `motion.${x.path}`, code: "dropped_on_minecraft", message: x.reason });
  return { ok: true, design: d, spec: r.spec, program: lo.program, errors: [], warnings, dropped: lo.dropped };
}

