// Cyrus r48: tolerant reader for a JSON document that is still being written (a spec streaming out of the model).
// PURE, no eval, hard caps. Returns the STABLE part of the prefix: every value it contains is fully parsed, except the
// containers that are still open, which hold only their finished members. An unfinished trailing member (a half
// string, a half number, a half object inside an array) is left out until it closes, so an interpreter never sees a
// value that will still change. `partialStrings: true` keeps a half string value (for a name that is typing).

export const PARTIAL_JSON_MAX_CHARS = 128 * 1024;
export const PARTIAL_JSON_MAX_DEPTH = 32;
export const PARTIAL_JSON_MAX_NODES = 40_000;

export type PartialJson = { value: unknown; complete: boolean; error: string | null; nodes: number };

type Opts = { partialStrings?: boolean };
class Stop extends Error {}

export function parsePartialJson(text: string, opts: Opts = {}): PartialJson {
  if (typeof text !== "string") return { value: undefined, complete: false, error: "not text", nodes: 0 };
  if (text.length > PARTIAL_JSON_MAX_CHARS) return { value: undefined, complete: false, error: "too large", nodes: 0 };
  let i = 0;
  let nodes = 0;
  let error: string | null = null;
  const n = text.length;
  const ws = () => { while (i < n && (text[i] === " " || text[i] === "\n" || text[i] === "\r" || text[i] === "\t")) i++; };
  const fail = (m: string): never => { error = m; throw new Stop(); };
  // Each reader returns [value, closed]; an unclosed value means the input ended inside it.
  const str = (): [string, boolean] => {
    i++; // opening quote
    let out = "";
    while (i < n) {
      const ch = text[i];
      if (ch === '"') { i++; return [out, true]; }
      if (ch !== "\\") { out += ch; i++; continue; }
      if (i + 1 >= n) return [out, false];
      const e = text[i + 1];
      if (e === "u") {
        if (i + 6 > n) return [out, false];
        const hex = text.slice(i + 2, i + 6);
        if (!/^[0-9a-fA-F]{4}$/.test(hex)) fail("bad escape");
        out += String.fromCharCode(parseInt(hex, 16)); i += 6; continue;
      }
      const map: Record<string, string> = { n: "\n", t: "\t", r: "\r", b: "\b", f: "\f", '"': '"', "\\": "\\", "/": "/" };
      if (!(e in map)) fail("bad escape");
      out += map[e]; i += 2;
    }
    return [out, false];
  };
  const value = (depth: number): [unknown, boolean] => {
    if (++nodes > PARTIAL_JSON_MAX_NODES) fail("too many values");
    if (depth > PARTIAL_JSON_MAX_DEPTH) fail("too deep");
    ws();
    if (i >= n) return [undefined, false];
    const ch = text[i];
    if (ch === "{") {
      i++;
      const obj: Record<string, unknown> = {};
      for (;;) {
        ws();
        if (i >= n) return [obj, false];
        if (text[i] === "}") { i++; return [obj, true]; }
        if (text[i] === ",") { i++; ws(); }
        if (i >= n) return [obj, false];
        if (text[i] === "}") { i++; return [obj, true]; }
        if (text[i] !== '"') fail("expected a key");
        const [k, kc] = str();
        if (!kc) return [obj, false];
        ws();
        if (i >= n) return [obj, false];
        if (text[i] !== ":") fail("expected :");
        i++;
        const at = i;
        const [v, vc] = value(depth + 1);
        if (k === "__proto__" || k === "constructor" || k === "prototype") { if (!vc) return [obj, false]; continue; }
        if (vc) obj[k] = v;
        else {
          if (v !== undefined && typeof v === "object") obj[k] = v; // an open container keeps its finished members
          else if (opts.partialStrings && typeof v === "string" && text[at + (text.slice(at).length - text.slice(at).trimStart().length)] === '"') obj[k] = v;
          return [obj, false];
        }
      }
    }
    if (ch === "[") {
      i++;
      const arr: unknown[] = [];
      for (;;) {
        ws();
        if (i >= n) return [arr, false];
        if (text[i] === "]") { i++; return [arr, true]; }
        if (text[i] === ",") { i++; ws(); }
        if (i >= n) return [arr, false];
        if (text[i] === "]") { i++; return [arr, true]; }
        const [v, vc] = value(depth + 1);
        if (vc) arr.push(v);
        else return [arr, false]; // the unfinished element waits until it closes
      }
    }
    if (ch === '"') return str();
    if (ch === "t" || ch === "f" || ch === "n") {
      const word = ch === "t" ? "true" : ch === "f" ? "false" : "null";
      const got = text.slice(i, i + word.length);
      if (word.startsWith(got) && got.length < word.length) { i = n; return [undefined, false]; }
      if (got !== word) fail("bad literal");
      i += word.length;
      return [ch === "t" ? true : ch === "f" ? false : null, true];
    }
    const m = /^-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?/.exec(text.slice(i, i + 64));
    if (!m) {
      if (/^-?$|^-?\d+\.$|^-?\d+(\.\d+)?[eE][+-]?$/.test(text.slice(i, i + 64))) { i = n; return [undefined, false]; }
      fail("bad value");
    }
    i += m![0].length;
    // a number at the very end may still be growing ("12" -> "123")
    if (i >= n) return [undefined, false];
    return [Number(m![0]), true];
  };
  let out: unknown;
  let complete = false;
  try {
    const [v, c] = value(0);
    out = v;
    complete = c;
    if (c) { ws(); if (i < n) { error = "trailing text"; complete = false; } }
  } catch (e) {
    if (!(e instanceof Stop)) throw e;
  }
  return { value: out, complete, error, nodes };
}

