// Cyrus r48 live asset streaming: the event shapes the build service sends (services/modbuilder/liveassets.js),
// as the forge stream carries them (GenEvent {type: "asset", ev}). Client-safe, no imports.

export const LIVE_ASSET_KINDS = ["texture", "sound", "datapack", "design", "creature", "itemmodel", "config", "library", "mesh"] as const;
export type LiveAssetKind = (typeof LIVE_ASSET_KINDS)[number];

/** Path rules = the service's (only these paths are ever shown). */
export const LIVE_ASSET_PATHS: { kind: LiveAssetKind; re: RegExp }[] = [
  { kind: "texture", re: /^assets\/textures\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "sound", re: /^assets\/sounds\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "datapack", re: /^assets\/datapack\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "design", re: /^assets\/designs\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "creature", re: /^assets\/creatures\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "itemmodel", re: /^assets\/itemmodels\/[a-z][a-z0-9_]{1,31}\.json$/ },
  { kind: "config", re: /^assets\/config\/schema\.json$/ },
  { kind: "library", re: /^assets\/library\.json$/ },
  { kind: "mesh", re: /^meshes\/[a-z][a-z0-9_]{1,31}$/ },
];
export function kindOfAssetPath(p: unknown): LiveAssetKind | null {
  if (typeof p !== "string" || p.length > 120 || p.includes("..")) return null;
  for (const k of LIVE_ASSET_PATHS) if (k.re.test(p)) return k.kind;
  return null;
}

export const LIVE_MAX_SPEC_CHARS = 64 * 1024;
export const LIVE_MAX_ASSETS = 48;
export const LIVE_MAX_TIMELINE = 400;
export const LIVE_MAX_MESH_IMAGE_CHARS = 280 * 1024;

export type LivePick = { id: string; kind: string; purpose: string; title?: string };

export type LiveAssetEvent =
  /** The spec being written right now (the text after `from`). */
  | { type: "partial"; kind: LiveAssetKind; path: string; seq: number; from: number; text: string; total: number; done: boolean; truncated?: boolean }
  /** A finished write: the file as it is now (absent when over the size cap). */
  | { type: "complete"; seq: number; kind: LiveAssetKind; path: string; op?: "write" | "edit"; bytes?: number; content?: string; truncated?: boolean; at?: number }
  | { type: "problems" | "validated" | "dropped" | "built"; seq: number; kind: LiveAssetKind | "build"; path: string; name?: string; info?: string[]; picks?: LivePick[]; at?: number }
  /** An AI mesh round render (Model Studio meshgen): one PNG per round. */
  | { type: "render"; seq: number; kind: "mesh"; path: string; round: number; image: string; at?: number };

/** Honest stage of one asset: drafting -> validated -> built; never "final" before compile + scan (+ flight, separate). */
export type LiveStage = "drafting" | "written" | "problems" | "validated" | "dropped" | "built";
export const STAGE_LABEL: Record<LiveStage, string> = {
  drafting: "Drafting",
  written: "Written, not checked yet",
  problems: "Needs a fix",
  validated: "Validated",
  dropped: "Left out",
  built: "Built",
};
export const STAGE_HINT: Record<LiveStage, string> = {
  drafting: "Cyrus is writing this spec right now",
  written: "Written; Nxeon's checks run when the code is done",
  problems: "Nxeon's checks found problems; Cyrus is fixing them",
  validated: "Passed Nxeon's checks. Not compiled yet",
  dropped: "Did not pass the checks, so it is left out of the mod",
  built: "Compiled and safety-scanned into the plugin. Test Flight is separate",
};

