// Cyrus r48: the live asset state of one build, folded from the asset events in order. PURE (unit-tested).
// Ordering rules: typed events carry the service's `seq` and are applied once (a re-attached stream re-sends them);
// drafts follow the code-draft protocol (same path + same tool-call seq = append after `from`, else start over).
import { LIVE_MAX_ASSETS, LIVE_MAX_MESH_IMAGE_CHARS, LIVE_MAX_SPEC_CHARS, LIVE_MAX_TIMELINE, kindOfAssetPath, type LiveAssetEvent, type LiveAssetKind, type LivePick, type LiveStage } from "./types";

export type LiveAsset = {
  path: string;
  kind: LiveAssetKind;
  name: string;
  stage: LiveStage;
  text: string;
  /** tool-call seq of the draft being followed */
  draftSeq: number;
  truncated: boolean;
  info: string[];
  picks: LivePick[];
  renders: { round: number; image: string }[];
  firstAt: number;
  updatedAt: number;
  /** bumps on every change, so renderers can memoise */
  rev: number;
};
export type LiveTimelineRow = { at: number; path: string; type: LiveAssetEvent["type"]; seq: number };
export type LiveState = {
  assets: Record<string, LiveAsset>;
  order: string[];
  /** the asset written most recently (auto-focus target) */
  writing: string | null;
  lastSeq: number;
  built: boolean;
  timeline: LiveTimelineRow[];
};

export const emptyLive = (): LiveState => ({ assets: {}, order: [], writing: null, lastSeq: 0, built: false, timeline: [] });

const nameOf = (path: string) => (path.split("/").pop() || path).replace(/\.json$/, "");

function upsert(s: LiveState, path: string, kind: LiveAssetKind, now: number): LiveAsset | null {
  const cur = s.assets[path];
  if (cur) return cur;
  if (s.order.length >= LIVE_MAX_ASSETS) return null;
  const a: LiveAsset = { path, kind, name: kind === "config" ? "settings" : kind === "library" ? "library picks" : nameOf(path), stage: "drafting", text: "", draftSeq: -1, truncated: false, info: [], picks: [], renders: [], firstAt: now, updatedAt: now, rev: 0 };
  s.assets = { ...s.assets, [path]: a };
  s.order = [...s.order, path];
  return a;
}
function put(s: LiveState, a: LiveAsset, patch: Partial<LiveAsset>, now: number) {
  s.assets = { ...s.assets, [a.path]: { ...a, ...patch, updatedAt: now, rev: a.rev + 1 } };
}
function log(s: LiveState, row: LiveTimelineRow) {
  s.timeline = s.timeline.length >= LIVE_MAX_TIMELINE ? [...s.timeline.slice(1), row] : [...s.timeline, row];
}

/** Apply one event; returns a NEW state object when anything changed (the same one otherwise). */
export function applyLive(prev: LiveState, ev: LiveAssetEvent, now = Date.now()): LiveState {
  if (!ev || typeof ev !== "object") return prev;
  const isBuild = ev.type === "built" && ev.kind === "build";
  const kind = isBuild ? null : kindOfAssetPath(ev.path);
  if (!isBuild && (!kind || (ev.kind !== kind))) return prev; // never shows a path outside the asset folders
  const s: LiveState = { ...prev };
  if (ev.type !== "partial") {
    if (!Number.isFinite(ev.seq) || ev.seq <= prev.lastSeq) return prev; // already applied
    s.lastSeq = ev.seq;
  }
  if (isBuild) {
    s.built = true;
    log(s, { at: ev.at ?? now, path: "", type: ev.type, seq: ev.seq });
    return s;
  }
  const a = upsert(s, ev.path, kind!, now);
  if (!a) return prev;
  switch (ev.type) {
    case "partial": {
      if (ev.truncated) { put(s, a, { stage: "drafting", truncated: true, draftSeq: ev.seq }, now); s.writing = a.path; break; }
      const same = a.draftSeq === ev.seq && a.stage === "drafting";
      let text: string;
      if (same) {
        if (ev.from > a.text.length) return prev; // a gap: wait for a resend from 0
        text = a.text.slice(0, ev.from) + ev.text;
      } else {
        if (ev.from !== 0) return prev;
        text = ev.text;
      }
      if (text.length > LIVE_MAX_SPEC_CHARS) { put(s, a, { truncated: true, draftSeq: ev.seq, stage: "drafting" }, now); break; }
      if (same && text === a.text) return prev;
      put(s, a, { text, draftSeq: ev.seq, stage: "drafting", truncated: false, info: [] }, now);
      s.writing = a.path;
      if (!same) log(s, { at: now, path: a.path, type: "partial", seq: ev.seq });
      break;
    }
    case "complete": {
      const content = typeof ev.content === "string" && ev.content.length <= LIVE_MAX_SPEC_CHARS ? ev.content : null;
      put(s, a, { text: content ?? a.text, truncated: content === null, stage: "written", info: [], draftSeq: -1 }, now);
      s.writing = a.path;
      log(s, { at: ev.at ?? now, path: a.path, type: ev.type, seq: ev.seq });
      break;
    }
    case "problems":
    case "validated":
    case "dropped":
    case "built": {
      // "built" only follows a validated spec (a dropped one never becomes built)
      if (ev.type === "built" && a.stage === "dropped") return prev;
      const stage: LiveStage = ev.type;
      put(s, a, {
        stage,
        info: Array.isArray(ev.info) ? ev.info.slice(0, 3).map((x) => String(x).slice(0, 200)) : [],
        ...(Array.isArray(ev.picks) ? { picks: ev.picks.slice(0, 12) } : {}),
        ...(ev.name && kind !== "config" && kind !== "library" ? { name: String(ev.name).slice(0, 40) } : {}),
      }, now);
      log(s, { at: ev.at ?? now, path: a.path, type: ev.type, seq: ev.seq });
      break;
    }
    case "render": {
      if (typeof ev.image !== "string" || ev.image.length > LIVE_MAX_MESH_IMAGE_CHARS || !/^data:image\/(png|webp|jpeg);base64,[A-Za-z0-9+/=]+$/.test(ev.image)) return prev;
      put(s, a, { renders: [...a.renders, { round: ev.round, image: ev.image }].slice(-6), stage: "written" }, now);
      s.writing = a.path;
      log(s, { at: ev.at ?? now, path: a.path, type: ev.type, seq: ev.seq });
      break;
    }
    default:
      return prev;
  }
  return s;
}

/** Fold a stored timeline (replay / reload). */
export function foldLive(events: LiveAssetEvent[], base = emptyLive()): LiveState {
  let s = base;
  for (const e of events.slice(0, 2000)) s = applyLive(s, e, e && "at" in e && typeof e.at === "number" ? e.at : Date.now());
  return s;
}

