input.content:
// Cyrus r48: what each live asset can SAFELY show, from its (possibly half-written) spec text. PURE, client-safe.
// Nothing here runs the spec: drafts are read with the tolerant partial reader and pass the SAME pure validators the
// studios use (texture checkSpec per op, sound checkSoundSpec, RigSpec checkRigSpec, MotionSpec schema) before an
// interpreter (texture render, motion sample) sees them; every list is capped. A value that fails stays unshown.
import { checkRigSpec, MAX_BONES, MAX_COORD, MAX_CUBES } from "../creature/spec";
import { MotionSpecSchema, type MotionSpec } from "../motion/spec";
import { presetById } from "../motion/presets";
import { checkSoundSpec, type SoundSpec } from "../sound/spec";
import { checkSpec, MAX_OPS, TEXTURE_SIZES, type Op, type TextureSpec } from "../textures/dsl";
import { parsePartialJson } from "./partial-json";
import type { LiveAsset } from "./state";

type O = Record<string, unknown>;
const isObj = (v: unknown): v is O => !!v && typeof v === "object" && !Array.isArray(v);
const arr = (v: unknown, cap: number): unknown[] => (Array.isArray(v) ? v.slice(0, cap) : []);
const s = (v: unknown, n = 60): string => (typeof v === "string" ? v.slice(0, n) : "");
const fin = (v: unknown, lo: number, hi: number): number | null => (typeof v === "number" && Number.isFinite(v) && v >= lo && v <= hi ? v : null);
const HEX = /^#[0-9a-fA-F]{6}$/;

export type ReadSpec = { value: unknown; complete: boolean; error: string | null };
export function readSpec(text: string): ReadSpec {
  const p = parsePartialJson(text, { partialStrings: true });
  return { value: p.value, complete: p.complete, error: p.error };
}

// ------------------------------------------------------------------------------------------------ texture
export type TextureView = { kind: "texture"; spec: TextureSpec | null; total: number; stoppedAt: string | null };
export function textureView(v: unknown): TextureView {
  if (!isObj(v)) return { kind: "texture", spec: null, total: 0, stoppedAt: null };
  const size = TEXTURE_SIZES.includes(v.size as 16) ? (v.size as TextureSpec["size"]) : null;
  const palette: Record<string, string> = {};
  if (isObj(v.palette)) for (const [k, c] of Object.entries(v.palette).slice(0, 24)) if (typeof c === "string" && HEX.test(c)) palette[k] = c;
  const ops = arr(v.ops, MAX_OPS);
  if (!size || !Object.keys(palette).length) return { kind: "texture", spec: null, total: ops.length, stoppedAt: null };
  const base = { name: typeof v.name === "string" && /^[a-z][a-z0-9_]{1,31}$/.test(v.name) ? v.name : "draft", size, palette, mirror: v.mirror === true };
  const ok: Op[] = [];
  let stoppedAt: string | null = null;
  for (const o of ops) {
    const r = checkSpec({ ...base, ops: [o] });
    if (!r.ok) { stoppedAt = r.error; break; }
    ok.push(r.spec.ops[0]);
  }
  return { kind: "texture", spec: ok.length ? { ...base, palette: Object.fromEntries(Object.entries(palette).map(([k, c]) => [k, c.toLowerCase()])), ops: ok } : null, total: ops.length, stoppedAt };
}

// ------------------------------------------------------------------------------------------------ sound
export type SoundLayerView = { source: string; start: number; length: number; gain: number };
export type SoundView = { kind: "sound"; name: string; events: { event: string; role: string; subtitle: string; variants: { layers: SoundLayerView[] }[] }[]; checked: SoundSpec | null; error: string | null };
export function soundView(v: unknown, complete: boolean): SoundView {
  const out: SoundView = { kind: "sound", name: isObj(v) ? s(v.name, 32) : "", events: [], checked: null, error: null };
  if (!isObj(v)) return out;
  for (const e of arr(v.events, 8)) {
    if (!isObj(e)) continue;
    const variants = arr(e.variants, 4).filter(isObj).map((va) => ({
      layers: arr(va.layers, 4).filter(isObj).map((l) => ({ source: s(l.source, 60), start: fin(l.start, 0, 30) ?? 0, length: fin(l.length, 0, 30) ?? 0.5, gain: fin(l.gain, -60, 12) ?? 0 })),
    }));
    out.events.push({ event: s(e.event, 24), role: s(e.role, 12), subtitle: s(e.subtitle, 80), variants });
  }
  if (complete) {
    const r = checkSoundSpec(v, { catalog: null, library: true });
    if (r.ok) out.checked = r.spec; else out.error = r.error;
  }
  return out;
}

// ------------------------------------------------------------------------------------------------ creature (RigSpec)
export type CubeView = { bone: string; from: [number, number, number]; to: [number, number, number]; color: string };
export type CreatureView = { kind: "creature"; bones: { name: string; parent: string | null; pivot: [number, number, number] }[]; cubes: CubeView[]; clips: string[]; ok: boolean | null; error: string | null };
const v3 = (v: unknown): [number, number, number] | null => {
  if (!Array.isArray(v) || v.length !== 3) return null;
  const x = v.map((n) => fin(n, -MAX_COORD, MAX_COORD));
  return x.every((n) => n !== null) ? (x as [number, number, number]) : null;
};
export function creatureView(v: unknown, complete: boolean): CreatureView {
  const out: CreatureView = { kind: "creature", bones: [], cubes: [], clips: [], ok: null, error: null };
  if (!isObj(v)) return out;
  const pal: Record<string, string> = {};
  const skin = isObj(v.skin) ? v.skin : {};
  if (isObj(skin.palette)) for (const [k, c] of Object.entries(skin.palette).slice(0, 16)) if (typeof c === "string" && HEX.test(c)) pal[k] = c.toLowerCase();
  for (const b of arr(v.bones, MAX_BONES)) {
    if (!isObj(b) || typeof b.name !== "string" || !/^[a-z][a-z0-9_]{0,23}$/.test(b.name)) continue;
    const pivot = v3(b.pivot) ?? [0, 0, 0];
    out.bones.push({ name: b.name, parent: typeof b.parent === "string" ? b.parent : null, pivot });
    for (const c of arr(b.cubes, 12)) {
      if (out.cubes.length >= MAX_CUBES || !isObj(c)) continue;
      const from = v3(c.from), to = v3(c.to);
      if (!from || !to) continue;
      out.cubes.push({ bone: b.name, from, to, color: (typeof c.material === "string" && pal[c.material]) || "#8a8f9c" });
    }
  }
  if (isObj(v.animations)) out.clips = Object.keys(v.animations).slice(0, 8);
  if (complete) {
    const r = checkRigSpec(v);
    out.ok = r.ok;
    if (!r.ok) out.error = (r as { issues?: { message: string }[] }).issues?.[0]?.message ?? "did not pass the creature checks";
  }
  return out;
}

// ------------------------------------------------------------------------------------------------ designs (graphs, motion)
export type GraphNode = { col: "when" | "if" | "do"; label: string };
export type AbilityView = { id: string; name: string; nodes: GraphNode[] };
export type TrackLane = { clip: string; length: number; kind: string; label: string; ticks: number[] };
export type DesignView = {
  kind: "design";
  dkind: string;
  id: string;
  title: string;
  stats: { key: string; value: string }[];
  abilities: AbilityView[];
  counts: { key: string; n: number }[];
  motion: { preset: string | null; params: { key: string; value: string }[]; lanes: TrackLane[]; spec: MotionSpec | null; error: string | null } | null;
};
function actionLabels(list: unknown, depth: number, out: string[]) {
  for (const a of arr(list, 16)) {
    if (!isObj(a) || out.length >= 12) continue;
    if (typeof a.type === "string") out.push(a.type.replace(/_/g, " "));
    if (depth < 2 && Array.isArray(a.actions)) actionLabels(a.actions, depth + 1, out);
  }
}
export function designView(v: unknown, complete: boolean): DesignView {
  const out: DesignView = { kind: "design", dkind: "item", id: "", title: "", stats: [], abilities: [], counts: [], motion: null };
  if (!isObj(v)) return out;
  out.dkind = s(v.kind, 16) || "item";
  out.id = s(v.id, 32);
  const nm = isObj(v.name) ? s(v.name.text, 60) : s(v.name, 60);
  out.title = s(v.title, 60) || nm || out.id;
