        lanes.push({ clip: s(c.name, 24), length: fin(c.length, 1, 72000) ?? 20, kind, label: kind === "transform" ? `${s(t.node, 24)} ${s(t.channel, 6)}` : kind === "sound" ? s(t.sound, 40) : kind === "event" ? s(t.name, 24) : s(t.node, 24) || kind, ticks });
