"use client";
// Cyrus r48: live asset state per build, kept apart from the studio store so a stream of asset events never
// re-renders the network. Events are batched per animation frame (throttle).
import { create } from "zustand";
import { applyLive, emptyLive, foldLive, type LiveState } from "./state";
import type { LiveAssetEvent } from "./types";

type S = {
  byBuild: Record<string, LiveState>;
  /** asset path the viewer pinned (holds the preview on it instead of following the writer) */
  pinned: Record<string, string | null>;
  apply: (buildId: string, evs: LiveAssetEvent[]) => void;
  load: (buildId: string, evs: LiveAssetEvent[]) => void;
  pin: (buildId: string, path: string | null) => void;
};
const MAX_BUILDS = 6;

export const useLiveAssets = create<S>((set) => ({
  byBuild: {},
  pinned: {},
  apply: (buildId, evs) =>
    set((st) => {
      let cur = st.byBuild[buildId] ?? emptyLive();
      const start = cur;
      for (const e of evs) cur = applyLive(cur, e);
      if (cur === start && st.byBuild[buildId]) return st;
      const keys = Object.keys(st.byBuild).filter((k) => k !== buildId).slice(-(MAX_BUILDS - 1));
      return { byBuild: { ...Object.fromEntries(keys.map((k) => [k, st.byBuild[k]])), [buildId]: cur } };
    }),
  load: (buildId, evs) => set((st) => ({ byBuild: { ...st.byBuild, [buildId]: foldLive(evs) } })),
  pin: (buildId, path) => set((st) => ({ pinned: { ...st.pinned, [buildId]: path } })),
}));

// rAF batching for the forge stream
const queue = new Map<string, LiveAssetEvent[]>();
let raf = 0;
export function pushLiveAsset(buildId: string, ev: LiveAssetEvent) {
  const q = queue.get(buildId) ?? [];
  if (q.length < 400) q.push(ev);
  queue.set(buildId, q);
  if (raf) return;
  const flush = () => {
    raf = 0;
    for (const [id, evs] of queue) useLiveAssets.getState().apply(id, evs);
    queue.clear();
  };
  raf = typeof requestAnimationFrame === "function" ? requestAnimationFrame(flush) : (setTimeout(flush, 16) as unknown as number);
}
