// Cyrus r48: turns the service's `assets` part of /live into forge-stream asset events (server side, PURE).
// Bounded: at most 80 typed events and one draft slice per poll; anything with a path outside the asset folders or a
// kind that does not match its path is dropped here too (the service already refuses them; defence in depth).
import type { SvcLiveAssets, SvcLiveAssetsQuery } from "../builder/client";
import { LIVE_MAX_SPEC_CHARS, kindOfAssetPath, type LiveAssetEvent } from "./types";

export type AssetFollow = { aseq: number; draft: { path: string; seq: number; len: number; done: boolean } | null };
export const newAssetFollow = (): AssetFollow => ({ aseq: 0, draft: null });

export function assetQuery(f: AssetFollow): SvcLiveAssetsQuery {
  const d = f.draft && !f.draft.done ? f.draft : null;
  return { aseq: f.aseq, ...(d ? { adraft: d.path, aseqd: d.seq, afrom: d.len } : {}) };
}

const TYPED = new Set(["complete", "problems", "validated", "dropped", "built"]);

export function assetEvents(f: AssetFollow, a: SvcLiveAssets | undefined | null): LiveAssetEvent[] {
  if (!a || typeof a !== "object") return [];
  const out: LiveAssetEvent[] = [];
  for (const raw of (Array.isArray(a.events) ? a.events : []).slice(0, 80)) {
    const e = raw as Record<string, unknown>;
    const seq = typeof e.seq === "number" && Number.isFinite(e.seq) ? e.seq : -1;
    if (seq <= f.aseq || !TYPED.has(String(e.type))) continue;
    f.aseq = seq;
    const isBuild = e.type === "built" && e.kind === "build";
    const kind = isBuild ? "build" : kindOfAssetPath(e.path);
    if (!kind || (!isBuild && e.kind !== kind)) continue;
    const base = { seq, kind, path: isBuild ? "" : String(e.path), ...(typeof e.at === "number" ? { at: e.at } : {}) };
    if (e.type === "complete") {
      const content = typeof e.content === "string" && e.content.length <= LIVE_MAX_SPEC_CHARS ? e.content : undefined;
      out.push({ type: "complete", ...base, kind: kind as Exclude<typeof kind, "build">, op: e.op === "edit" ? "edit" : "write", ...(content !== undefined ? { content } : { truncated: true }) });
    } else {
      out.push({
        type: e.type as "validated", ...base, kind: kind as "texture",
        ...(typeof e.name === "string" ? { name: e.name.slice(0, 40) } : {}),
        ...(Array.isArray(e.info) ? { info: e.info.slice(0, 3).map((x) => String(x).slice(0, 200)) } : {}),
        ...(Array.isArray(e.picks) ? { picks: (e.picks as Record<string, unknown>[]).slice(0, 12).map((p) => ({ id: String(p.id ?? "").slice(0, 48), kind: String(p.kind ?? "").slice(0, 12), purpose: String(p.purpose ?? "").slice(0, 160), ...(typeof p.title === "string" ? { title: p.title.slice(0, 80) } : {}) })) } : {}),
      });
    }
  }
  if (typeof a.seq === "number" && a.seq > f.aseq && !a.gap) f.aseq = Math.max(f.aseq, Math.min(a.seq, f.aseq + 80));
  const d = a.draft;
  if (d && typeof d === "object") {
    const kind = kindOfAssetPath(d.path);
    if (kind && kind === d.kind && d.op === "write") {
      const same = f.draft && f.draft.path === d.path && f.draft.seq === d.seq;
      if (!same) f.draft = { path: d.path, seq: d.seq, len: 0, done: false };
      const cur = f.draft!;
      if (d.truncated) out.push({ type: "partial", kind, path: d.path, seq: d.seq, from: 0, text: "", total: d.total, done: !!d.done, truncated: true });
      else if (typeof d.text === "string" && d.from <= cur.len && d.from + d.text.length <= LIVE_MAX_SPEC_CHARS && (d.text.length || !same)) {
        out.push({ type: "partial", kind, path: d.path, seq: d.seq, from: d.from, text: d.text, total: d.total, done: !!d.done });
        cur.len = d.from + d.text.length;
      }
      if (d.done) cur.done = true;
    }
  }
  return out;
}
EOF

