import { NextResponse } from "next/server";
import { svcLive } from "@/lib/modbuilder/client";
import { getHost } from "@/lib/cyrus/host";
import { liveAssetsOn } from "@/lib/cyrus/liveassets/flags";
import { assetEvents, newAssetFollow } from "@/lib/cyrus/liveassets/follow-assets";
import { checkRateLimit } from "@/lib/rate-limit";
import { NOT_FOUND, ownedBuild } from "../../../_lib";

export const dynamic = "force-dynamic";

// Cyrus r48: the stored asset timeline of one of the user's builds (replay + final gallery). Off (404) unless
// CYRUS_LIVE_ASSETS=1. Only asset spec paths, already bounded by the service (160 events, 384 KB).
export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  if (!liveAssetsOn()) return NOT_FOUND();
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const rl = checkRateLimit(`mb:liveassets:${o.user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) return NextResponse.json({ error: "Slow down" }, { status: 429 });
  try {
    const sid = await getHost().mods.serviceBuildId(o.build.id);
    const live = await svcLive(sid, undefined, 0, 0, { aseq: 0 });
    const events = assetEvents(newAssetFollow(), live?.assets).filter((e) => e.type !== "partial");
    return NextResponse.json({ events, status: o.build.status }, { headers: { "Cache-Control": "no-store" } });
  } catch {
    return NextResponse.json({ error: "The builder is offline right now." }, { status: 503 });
  }
}
