"use client";
// Cyrus r48: per-kind live renderers. They only ever draw views made by lib/cyrus/liveassets/interpret.ts (validated,
// capped); the pure interpreters (texture render, motion sample, sound render) run here, nothing else. Every animation
// pauses offscreen / in a hidden tab, is skipped with reduced motion, and runs slower on low-end devices.
import { useEffect, useMemo, useRef, useState } from "react";
import type { ConfigView, CreatureView, DatapackView, DesignView, ItemModelView, LibraryView, MeshView, SoundView, TextureView } from "@/lib/cyrus/liveassets/interpret";
import { render as renderTexture } from "@/lib/cyrus/textures/render";
import type { TextureSpec } from "@/lib/cyrus/textures/dsl";
import { nodePositions, sample } from "@/lib/cyrus/motion";
import { renderVariant } from "@/lib/cyrus/sound/render";
import { peaksOf } from "@/lib/cyrus/sound/peaks";
import { SAMPLE_RATE } from "@/lib/cyrus/sound/dsp";

// ------------------------------------------------------------------------------------------- shared hooks
export function useReducedMotion(): boolean {
  const [r, setR] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const m = window.matchMedia("(prefers-reduced-motion: reduce)");
    const on = () => setR(m.matches);
    on();
    m.addEventListener?.("change", on);
    return () => m.removeEventListener?.("change", on);
  }, []);
  return r;
}
/** Visible on screen AND the tab is visible (animations pause otherwise). */
export function useVisible<T extends Element>(ref: React.RefObject<T | null>): boolean {
  const [inView, setInView] = useState(true);
  const [tab, setTab] = useState(true);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver((es) => setInView(es.some((e) => e.isIntersecting)), { threshold: 0.05 });
    io.observe(el);
    return () => io.disconnect();
  }, [ref]);
  useEffect(() => {
    const on = () => setTab(document.visibilityState !== "hidden");
    on();
    document.addEventListener("visibilitychange", on);
    return () => document.removeEventListener("visibilitychange", on);
  }, []);
  return inView && tab;
}
export function lowEndDevice(): boolean {
  if (typeof navigator === "undefined") return false;
  const n = navigator as Navigator & { deviceMemory?: number };
  return (n.hardwareConcurrency ?? 8) <= 4 || (n.deviceMemory ?? 8) <= 4;
}
/** Animate a counter from what is shown toward `target` (stroke by stroke); jumps with reduced motion / offscreen. */
function useCatchUp(target: number, run: boolean, perTick: (behind: number) => number, ms: number): number {
  const [shown, setShown] = useState(run ? 0 : target);
  useEffect(() => {
    if (shown > target) setShown(target);
  }, [target, shown]);
  useEffect(() => {
    if (!run) { setShown(target); return; }
    if (shown >= target) return;
    const t = window.setTimeout(() => setShown((s) => Math.min(target, s + Math.max(1, perTick(target - s)))), ms);
    return () => window.clearTimeout(t);
  }, [run, shown, target, perTick, ms]);
  return Math.min(shown, target);
}

const Empty = ({ children }: { children: React.ReactNode }) => <div className="grid h-full min-h-[120px] place-items-center px-4 text-center text-[12px] text-cy-muted">{children}</div>;

// ------------------------------------------------------------------------------------------- texture
export function TextureLive({ view, compact }: { view: TextureView; compact?: boolean }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const box = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const visible = useVisible(box);
  const low = useMemo(lowEndDevice, []);
  const spec = view.spec;
  const total = spec?.ops.length ?? 0;
  const step = useMemo(() => (behind: number) => (low ? Math.ceil(behind / 6) : behind > 40 ? Math.ceil(behind / 20) : 1), [low]);
  const shown = useCatchUp(total, !reduced && visible && !compact, step, low ? 90 : 45);
  useEffect(() => {
    const c = ref.current;
    if (!c || !spec) return;
    const part: TextureSpec = { ...spec, ops: spec.ops.slice(0, Math.max(1, shown)) };
    const r = renderTexture(part);
    c.width = r.size;
    c.height = r.size;
    const ctx = c.getContext("2d");
    if (!ctx) return;
    ctx.putImageData(new ImageData(new Uint8ClampedArray(r.px), r.size, r.size), 0, 0);
  }, [spec, shown]);
  if (!spec) return <Empty>{view.total ? "Reading the palette and canvas…" : "Waiting for the first stroke…"}</Empty>;
  return (
    <div ref={box} className="flex h-full flex-col items-center justify-center gap-2 p-3">
      <div className="relative rounded-lg bg-[repeating-conic-gradient(rgb(var(--glow)/0.08)_0_25%,transparent_0_50%)] bg-[length:12px_12px] p-2">
        <canvas ref={ref} role="img" aria-label={`Texture ${spec.name}, ${shown} of ${total} drawing steps`} className={compact ? "h-16 w-16" : "h-40 w-40 sm:h-48 sm:w-48"} style={{ imageRendering: "pixelated" }} />
      </div>
      {!compact && (
        <div className="font-mono text-[11px] tabular-nums text-cy-muted">
          {spec.size}×{spec.size} · step {shown}/{total}
          {spec.ops[shown - 1] ? <span className="ml-1 text-cy-ink-2">· {spec.ops[shown - 1].op}</span> : null}
          {view.stoppedAt ? <span className="ml-1 text-cy-faint">· waiting: {view.stoppedAt}</span> : null}
        </div>
      )}
    </div>
  );
}

/** A finished texture as a tiny static thumbnail (gallery / item model states). */
export function TextureThumb({ spec, size = 40 }: { spec: TextureSpec; size?: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const c = ref.current;
    if (!c) return;
    const r = renderTexture(spec);
    c.width = r.size; c.height = r.size;
    c.getContext("2d")?.putImageData(new ImageData(new Uint8ClampedArray(r.px), r.size, r.size), 0, 0);
  }, [spec]);
  return <canvas ref={ref} aria-hidden style={{ width: size, height: size, imageRendering: "pixelated" }} />;
}

// ------------------------------------------------------------------------------------------- creature (RigSpec cubes)
type Quad = { pts: [number, number][]; depth: number; fill: string };
const shadeHex = (hex: string, k: number) => {
  const n = parseInt(hex.slice(1), 16);
  const c = (v: number) => Math.max(0, Math.min(255, Math.round(v * k)));
  return `rgb(${c((n >> 16) & 255)} ${c((n >> 8) & 255)} ${c(n & 255)})`;
};
function drawCubes(ctx: CanvasRenderingContext2D, w: number, h: number, cubes: CreatureView["cubes"], angle: number) {
  ctx.clearRect(0, 0, w, h);
  if (!cubes.length) return;
  const ca = Math.cos(angle), sa = Math.sin(angle);
  const tilt = 0.5;
  const proj = (x: number, y: number, z: number): [number, number, number] => {
    const rx = x * ca - z * sa, rz = x * sa + z * ca;
    return [rx, -y + rz * tilt * 0.6, rz];
  };
  const quads: Quad[] = [];
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const c of cubes) {
    const [x0, y0, z0] = c.from, [x1, y1, z1] = c.to;
    const P = (x: number, y: number, z: number) => proj(x, y, z);
    const faces: { v: [number, number, number][]; light: number }[] = [
      { v: [P(x0, y1, z0), P(x1, y1, z0), P(x1, y1, z1), P(x0, y1, z1)], light: 1.12 }, // up
      { v: [P(x0, y0, z1), P(x1, y0, z1), P(x1, y1, z1), P(x0, y1, z1)], light: 0.92 }, // south
      { v: [P(x1, y0, z0), P(x1, y0, z1), P(x1, y1, z1), P(x1, y1, z0)], light: 0.78 }, // east
      { v: [P(x0, y0, z0), P(x1, y0, z0), P(x1, y1, z0), P(x0, y1, z0)], light: 0.7 }, // north
      { v: [P(x0, y0, z0), P(x0, y0, z1), P(x0, y1, z1), P(x0, y1, z0)], light: 0.66 }, // west
    ];
    for (const f of faces) {
      const pts = f.v.map((p) => [p[0], p[1]] as [number, number]);
      const area = pts.reduce((a, p, i) => { const q = pts[(i + 1) % pts.length]; return a + (p[0] * q[1] - q[0] * p[1]); }, 0);
      if (Math.abs(area) < 1e-6) continue;
      for (const p of pts) { minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]); minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]); }
      quads.push({ pts, depth: f.v.reduce((a, p) => a + p[2], 0) / 4 + (f.light > 1 ? 0.01 : 0), fill: shadeHex(c.color, f.light) });
    }
  }
  quads.sort((a, b) => a.depth - b.depth);
  const pad = 14;
  const s = Math.min((w - pad * 2) / Math.max(1, maxX - minX), (h - pad * 2) / Math.max(1, maxY - minY));
  const ox = w / 2 - ((minX + maxX) / 2) * s, oy = h / 2 - ((minY + maxY) / 2) * s;
  for (const q of quads) {
    ctx.beginPath();
    q.pts.forEach((p, i) => (i ? ctx.lineTo(ox + p[0] * s, oy + p[1] * s) : ctx.moveTo(ox + p[0] * s, oy + p[1] * s)));
    ctx.closePath();
    ctx.fillStyle = q.fill;
    ctx.fill();
    ctx.strokeStyle = "rgb(0 0 0 / 0.25)";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}
export function CreatureLive({ view, compact }: { view: CreatureView; compact?: boolean }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const box = useRef<HTMLDivElement>(null);
  const reduced = useReducedMotion();
  const visible = useVisible(box);
  const low = useMemo(lowEndDevice, []);
  const total = view.cubes.length;
  const step = useMemo(() => (behind: number) => (behind > 12 ? Math.ceil(behind / 6) : 1), []);
  const shown = useCatchUp(total, !reduced && visible && !compact, step, low ? 220 : 120);
  const [angle, setAngle] = useState(0.6);
  const spin = !reduced && visible && !low && !compact;
  useEffect(() => {
    if (!spin) return;
    let raf = 0, last = 0;
    const tick = (t: number) => {
      if (t - last > 50) { last = t; setAngle((a) => a + 0.02); }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [spin]);
  useEffect(() => {
    const c = ref.current;
    const ctx = c?.getContext("2d");
    if (!c || !ctx) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    const w = c.clientWidth || 220, h = c.clientHeight || 180;
    if (c.width !== Math.round(w * dpr)) { c.width = Math.round(w * dpr); c.height = Math.round(h * dpr); }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    drawCubes(ctx, w, h, view.cubes.slice(0, shown), angle);
  }, [view.cubes, shown, angle]);
  if (!total) return <Empty>{view.bones.length ? `${view.bones.length} bone${view.bones.length > 1 ? "s" : ""} so far, waiting for cubes…` : "Waiting for the first bone…"}</Empty>;
  return (
    <div ref={box} className="flex h-full flex-col gap-2 p-3">
      <canvas ref={ref} role="img" aria-label={`Model with ${shown} of ${total} cubes`} className={compact ? "h-20 w-full" : "h-48 w-full sm:h-56"} />
      {!compact && (
        <div className="flex flex-wrap items-center gap-1.5 text-[11px] text-cy-muted">
          <span className="font-mono tabular-nums">{view.bones.length} bones · {shown}/{total} cubes</span>
          {view.clips.map((c) => <span key={c} className="rounded-md bg-[rgb(var(--glow)/0.08)] px-1.5 py-0.5 font-mono text-[10.5px] text-cy-ink-2">{c}</span>)}
          {view.ok === false && view.error ? <span className="text-cy-faint">· {view.error}</span> : null}
          <span className="text-cy-faint">· rest pose</span>
        </div>
      )}
    </div>
  );
}

// ------------------------------------------------------------------------------------------- sound
function Wave({ peaks, label }: { peaks: number[]; label: string }) {
  return (
    <svg viewBox={`0 0 ${peaks.length} 40`} preserveAspectRatio="none" className="h-10 w-full" role="img" aria-label={label}>
      {peaks.map((p, i) => <rect key={i} x={i + 0.15} width={0.7} y={20 - Math.max(0.6, p * 19)} height={Math.max(1.2, p * 38)} rx={0.3} fill="var(--cy-cyan, #22d3ee)" opacity={0.85} />)}
    </svg>
  );
}
export function SoundLive({ view, ready, compact }: { view: SoundView; ready: boolean; compact?: boolean }) {
  const low = useMemo(lowEndDevice, []);
  const [rendered, setRendered] = useState<Record<string, { peaks: number[]; pcm: Float32Array; seconds: number }>>({});
  const [want, setWant] = useState(false);
  const ctxRef = useRef<AudioContext | null>(null);
  const checked = view.checked;
  // waveform once the recipe passed the sound checks: synth layers rendered here; library layers play after the host render
  useEffect(() => {
    if (!checked || !ready || (low && !want) || compact) return;
    const out: typeof rendered = {};
    let total = 0;
    for (const e of checked.events.slice(0, 8)) {
      const v = e.variants[0];
      if (!v) continue;
      try {
        const r = renderVariant(v, e.role, () => new Float64Array(Math.round(0.25 * SAMPLE_RATE)));
        const seconds = r.pcm.length / SAMPLE_RATE;
        total += seconds;
        if (total > 30) break;
        out[e.event] = { peaks: peaksOf(r.pcm, 72), pcm: Float32Array.from(r.pcm), seconds };
      } catch { /* a recipe the browser cannot render stays as its layer lanes */ }
    }
    setRendered(out);
  }, [checked, ready, low, want, compact]);
  useEffect(() => () => { void ctxRef.current?.close().catch(() => {}); }, []);
  const play = (ev: string) => {
    const r = rendered[ev];
    if (!r) return;
    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctx) return;
    const ctx = ctxRef.current ?? new Ctx();
    ctxRef.current = ctx;
    const buf = ctx.createBuffer(1, r.pcm.length, SAMPLE_RATE);
    buf.copyToChannel(r.pcm as Float32Array<ArrayBuffer>, 0);
    const src = ctx.createBufferSource();
    src.buffer = buf;
    src.connect(ctx.destination);
    src.start();
  };
  if (!view.events.length) return <Empty>Waiting for the first sound event…</Empty>;
  const maxT = Math.max(0.5, ...view.events.flatMap((e) => (e.variants[0]?.layers ?? []).map((l) => l.start + l.length)));
  return (
    <div className="flex flex-col gap-2 p-3">
      {view.events.slice(0, compact ? 2 : 8).map((e) => {
        const r = rendered[e.event];
        return (
          <div key={e.event} className="rounded-xl border border-cy-line px-2.5 py-2">
            <div className="flex items-center gap-2 text-[12px]">
              <span className="font-medium text-cy-ink">{e.event || "…"}</span>
              <span className="text-[10.5px] text-cy-muted">{e.role}{e.variants.length > 1 ? ` · ${e.variants.length} variants` : ""}</span>
              <span className="flex-1" />
              {r && !compact && (
                <button type="button" onClick={() => play(e.event)} className="cy5-btn-ghost h-6 px-2 text-[11px]" aria-label={`Play ${e.event} (synth layers)`}>
                  ▶ Play
                </button>
              )}
            </div>
            {r ? (
              <Wave peaks={r.peaks} label={`Waveform of ${e.event}, ${r.seconds.toFixed(2)} seconds`} />
            ) : (
              <div className="relative mt-1.5 h-[22px]" aria-label={`Recipe of ${e.event}`}>
                {(e.variants[0]?.layers ?? []).map((l, i) => (
                  <span key={i} title={l.source} className="absolute top-0 h-full overflow-hidden truncate rounded-md bg-[rgb(var(--glow)/0.14)] px-1 font-mono text-[9.5px] leading-[22px] text-cy-ink-2"
                    style={{ left: `${(l.start / maxT) * 100}%`, width: `${Math.max(6, (l.length / maxT) * 100)}%`, top: i * 2 }}>
                    {l.source.replace(/^synth:/, "").replace(/^lib:/, "lib ")}
                  </span>
                ))}
              </div>
            )}
          </div>
        );
      })}
      {!compact && (
        <div className="text-[11px] text-cy-faint">
          {checked ? (Object.keys(rendered).length ? "Preview renders synth layers here; library layers and loudness come from Nxeon's render host after the build." : low ? <button type="button" className="underline" onClick={() => setWant(true)}>Render a preview</button> : ready ? "Rendering a preview…" : "Waveform after Nxeon's sound checks pass.") : view.error ? `Not playable yet: ${view.error}` : "Layers appear as Cyrus writes the recipe."}
        </div>
      )}
    </div>
  );
}

// ------------------------------------------------------------------------------------------- designs: ability graph + motion
export function DesignLive({ view, playable, compact }: { view: DesignView; playable: boolean; compact?: boolean }) {
