function MotionLive({ view, playable, compact }: { view: DesignView; playable: boolean; compact?: boolean }) {
  const m = view.motion!;
  const box = useRef<HTMLDivElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const reduced = useReducedMotion();
  const visible = useVisible(box);
  const low = useMemo(lowEndDevice, []);
  const spec = playable ? m.spec : null;
  const clip = spec?.clips[0];
  const [tick, setTick] = useState(0);
  const run = !!clip && visible && !reduced && !compact;
  useEffect(() => {
    if (!run || !clip) return;
    const id = window.setInterval(() => setTick((t) => (t + (low ? 2 : 1)) % Math.max(1, clip.length + 10)), low ? 100 : 50);
    return () => window.clearInterval(id);
  }, [run, clip, low]);
  useEffect(() => {
    const c = canvas.current;
    const ctx = c?.getContext("2d");
    if (!c || !ctx || !spec || !clip) return;
    const w = c.clientWidth || 220, h = c.clientHeight || 120, dpr = Math.min(2, window.devicePixelRatio || 1);
    if (c.width !== Math.round(w * dpr)) { c.width = Math.round(w * dpr); c.height = Math.round(h * dpr); }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    let pos: Record<string, [number, number, number]>;
    try { pos = nodePositions(spec, sample(spec, clip.name, Math.min(tick, clip.length))) as Record<string, [number, number, number]>; } catch { return; }
    const nodes = spec.rig.nodes.slice(0, 48);
    const xs = nodes.map((n) => pos[n.name]?.[0] ?? 0), ys = nodes.map((n) => pos[n.name]?.[1] ?? 0);
    const span = Math.max(1, Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)) * 1.6;
    const s = Math.min(w, h) / span;
    const cx = w / 2 - ((Math.max(...xs) + Math.min(...xs)) / 2) * s, cy = h * 0.62 + ((Math.max(...ys) + Math.min(...ys)) / 2) * s;
    for (const n of nodes) {
      const p = pos[n.name];
      if (!p) continue;
      const par = n.parent ? pos[n.parent] : null;
      if (par) { ctx.strokeStyle = "rgb(148 163 184 / 0.5)"; ctx.beginPath(); ctx.moveTo(cx + par[0] * s, cy - par[1] * s); ctx.lineTo(cx + p[0] * s, cy - p[1] * s); ctx.stroke(); }
      const px = n.proxy;
      if (px) {
        ctx.fillStyle = px.color ?? "#a78bfa";
        ctx.globalAlpha = 0.85;
        ctx.fillRect(cx + (p[0] - px.size[0] / 2) * s, cy - (p[1] + px.size[1] / 2) * s, Math.max(2, px.size[0] * s), Math.max(2, px.size[1] * s));
        ctx.globalAlpha = 1;
      } else { ctx.fillStyle = "#22d3ee"; ctx.beginPath(); ctx.arc(cx + p[0] * s, cy - p[1] * s, 3, 0, Math.PI * 2); ctx.fill(); }
    }
  }, [spec, clip, tick]);
  const lanes = m.lanes.slice(0, compact ? 3 : 24);
  return (
    <div ref={box} className="flex flex-col gap-2 p-3">
      <div className="flex flex-wrap items-baseline gap-2">
        <span className="font-cy-display text-[13.5px] font-semibold text-cy-ink">{view.title || "…"}</span>
        <span className="text-[11px] text-cy-muted">motion{m.preset ? ` · preset ${m.preset}` : ""}</span>
      </div>
      {m.params.length > 0 && !compact && <div className="flex flex-wrap gap-1.5">{m.params.map((p) => <span key={p.key} className="rounded-md bg-[rgb(var(--glow)/0.08)] px-1.5 py-0.5 font-mono text-[10.5px] text-cy-ink-2">{p.key} {p.value}</span>)}</div>}
      {spec && clip && !compact && <canvas ref={canvas} role="img" aria-label={`Simulation of ${clip.name}, tick ${tick}`} className="h-28 w-full rounded-lg bg-[rgb(var(--glow)/0.04)]" />}
      <div className="flex flex-col gap-1" aria-label="Motion timeline">
        {lanes.map((l, i) => (
          <div key={i} className="flex items-center gap-2">
            <span className="w-28 shrink-0 truncate font-mono text-[10.5px] text-cy-muted" title={`${l.clip} · ${l.label}`}>{l.label || l.kind}</span>
            <div className="relative h-3 flex-1 rounded bg-[rgb(var(--glow)/0.07)]">
              {l.ticks.slice(0, 24).map((t, k) => <span key={k} className="absolute top-0.5 h-2 w-2 -translate-x-1 rotate-45 rounded-[2px] bg-cy-cyan" style={{ left: `${Math.min(100, (t / l.length) * 100)}%` }} />)}
              {spec && clip && l.clip === clip.name && <span className="absolute inset-y-0 w-px bg-cy-pink" style={{ left: `${Math.min(100, (Math.min(tick, clip.length) / clip.length) * 100)}%` }} />}
            </div>
          </div>
        ))}
        {!lanes.length && <span className="text-[12px] text-cy-muted">{m.preset ? "Built from the preset once the spec is checked." : "Tracks appear as Cyrus writes them."}</span>}
      </div>
      {!compact && <div className="text-[11px] text-cy-faint">{spec ? "Simulated in the browser from the checked spec (motion core, positions only)." : m.error ? `Not playable yet: ${m.error}` : "Plays once the spec passes the motion checks."}</div>}
    </div>
  );
}

