"use client";
// Cyrus r48: live asset previews next to the code stream. Tabs per asset (auto-focus on whichever is being written,
// pin to hold), honest stage labels (Drafting / Validated / Built: never "final" before compile + scan; Test Flight is
// separate), a gallery once the build is done, and a replay of the build's stored asset timeline. Phone = compact,
// read-only strip. Everything shown comes from the build's own asset specs via lib/cyrus/liveassets.
import { memo, useEffect, useMemo, useRef, useState } from "react";
import { viewOf, type AssetView } from "@/lib/cyrus/liveassets/interpret";
import { applyLive, emptyLive, type LiveAsset, type LiveState } from "@/lib/cyrus/liveassets/state";
import { useLiveAssets } from "@/lib/cyrus/liveassets/store";
import { STAGE_HINT, STAGE_LABEL, type LiveAssetEvent, type LiveAssetKind, type LiveStage } from "@/lib/cyrus/liveassets/types";
import type { TextureSpec } from "@/lib/cyrus/textures/dsl";
import { ConfigLive, CreatureLive, DatapackLive, DesignLive, ItemModelLive, LibraryLive, MeshLive, SoundLive, TextureLive, TextureThumb, useReducedMotion } from "./renderers";

const KIND_LABEL: Record<LiveAssetKind, string> = { texture: "Texture", sound: "Sound", datapack: "Data pack", design: "Design", creature: "Model", itemmodel: "Item states", config: "Settings", library: "Library", mesh: "AI mesh" };
const KIND_GLYPH: Record<LiveAssetKind, string> = { texture: "▦", sound: "♪", datapack: "⛰", design: "◇", creature: "◩", itemmodel: "◫", config: "⚙", library: "▤", mesh: "△" };
const STAGE_TONE: Record<LiveStage, string> = {
  drafting: "bg-[rgb(34_211_238/0.14)] text-cy-cyan",
  written: "bg-[rgb(var(--glow)/0.1)] text-cy-ink-2",
  problems: "bg-[rgb(251_191_36/0.16)] text-[#f59e0b]",
  validated: "bg-[rgb(52_211_153/0.15)] text-[#10b981]",
  dropped: "bg-[rgb(244_63_94/0.14)] text-[#f43f5e]",
  built: "bg-[rgb(167_139_250/0.18)] text-cy-accent-ink",
};

export function StagePill({ stage }: { stage: LiveStage }) {
  return (
    <span className={`inline-flex shrink-0 items-center gap-1 rounded-full px-2 py-0.5 text-[10.5px] font-medium ${STAGE_TONE[stage]}`} title={STAGE_HINT[stage]}>
      {stage === "drafting" && <span className="cy-live-dot h-1.5 w-1.5 rounded-full bg-current" aria-hidden />}
      {STAGE_LABEL[stage]}
    </span>
  );
}

function textureSpecs(state: LiveState): Record<string, TextureSpec> {
  const out: Record<string, TextureSpec> = {};
  for (const p of state.order) {
    const a = state.assets[p];
    if (a.kind !== "texture") continue;
    const v = viewOf(a);
    if (v.kind === "texture" && v.spec) out[a.name] = v.spec;
  }
  return out;
}

const Preview = memo(function Preview({ asset, view, textures, compact }: { asset: LiveAsset; view: AssetView; textures: Record<string, TextureSpec>; compact?: boolean }) {
  const settled = asset.stage === "validated" || asset.stage === "built";
  switch (view.kind) {
    case "texture": return <TextureLive view={view} compact={compact} />;
    case "creature": return <CreatureLive view={view} compact={compact} />;
    case "sound": return <SoundLive view={view} ready={settled || (asset.stage === "written" && !!view.checked)} compact={compact} />;
    case "design": return <DesignLive view={view} playable={settled || asset.stage === "written"} compact={compact} />;
    case "config": return <ConfigLive view={view} compact={compact} />;
    case "datapack": return <DatapackLive view={view} compact={compact} />;
    case "itemmodel": return <ItemModelLive view={view} textures={textures} compact={compact} />;
    case "library": return <LibraryLive view={view} />;
    case "mesh": return <MeshLive view={view} />;
  }
});

function useView(asset: LiveAsset | undefined): AssetView | null {
  // parse + validate once per change of the asset (rev), never per frame
  return useMemo(() => (asset ? viewOf(asset) : null), [asset?.rev, asset?.path]); // eslint-disable-line react-hooks/exhaustive-deps
}

/** Replays a stored timeline into a local state (compressed time; reduced motion = instantly). */
function useReplay(events: LiveAssetEvent[] | null, on: boolean, reduced: boolean): LiveState | null {
  const [st, setSt] = useState<LiveState | null>(null);
  useEffect(() => {
    if (!on || !events) { setSt(null); return; }
    if (reduced) { let s = emptyLive(); for (const e of events) s = applyLive(s, e); setSt(s); return; }
    let s = emptyLive();
    let i = 0;
    let t = 0;
    setSt(s);
    const next = () => {
      if (i >= events.length) return;
      s = applyLive(s, events[i++]);
      setSt(s);
      t = window.setTimeout(next, 650);
    };
    t = window.setTimeout(next, 250);
    return () => window.clearTimeout(t);
  }, [events, on, reduced]);
  return st;
}

export function LiveAssets({ buildId, streaming, compact, fetchStored }: { buildId: string; streaming: boolean; compact?: boolean; fetchStored?: boolean }) {
  const liveState = useLiveAssets((s) => s.byBuild[buildId]);
  const pinned = useLiveAssets((s) => s.pinned[buildId] ?? null);
  const pin = useLiveAssets((s) => s.pin);
  const load = useLiveAssets((s) => s.load);
  const reduced = useReducedMotion();
  const [stored, setStored] = useState<LiveAssetEvent[] | null>(null);
  const [replaying, setReplaying] = useState(false);
  const [picked, setPicked] = useState<string | null>(null);
  const tried = useRef<string | null>(null);

  // a finished build seen after a reload: its stored timeline (404 when the feature is off: shows nothing)
  useEffect(() => {
    if (streaming || !fetchStored || tried.current === buildId) return;
    tried.current = buildId;
    const ac = new AbortController();
    fetch(`/api/mod-builder/builds/${encodeURIComponent(buildId)}/live-assets`, { signal: ac.signal })
      .then((r) => (r.ok ? r.json() : null))
      .then((j: { events?: LiveAssetEvent[] } | null) => {
        if (!j?.events?.length) return;
        setStored(j.events);
        if (!useLiveAssets.getState().byBuild[buildId]?.order.length) load(buildId, j.events);
      })
      .catch(() => {});
    return () => ac.abort();
  }, [buildId, streaming, fetchStored, load]);

  const replay = useReplay(stored, replaying, reduced);
  useEffect(() => {
    if (replaying && replay && stored && replay.lastSeq >= (stored[stored.length - 1] as { seq?: number })?.seq!) {
      const t = window.setTimeout(() => setReplaying(false), 1500);
      return () => window.clearTimeout(t);
    }
  }, [replaying, replay, stored]);

  const state = (replaying ? replay : liveState) ?? null;
  const textures = useMemo(() => (state ? textureSpecs(state) : {}), [state?.assets]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!state || !state.order.length) return null;
  const done = !streaming && !replaying;
  const focusPath = (picked && state.assets[picked] ? picked : null) ?? (pinned && state.assets[pinned] ? pinned : null) ?? state.writing ?? state.order[state.order.length - 1];
  const asset = state.assets[focusPath];
  const isPinned = !!pinned && pinned === focusPath;
  const select = (p: string) => { setPicked(p); if (pinned && !compact) pin(buildId, p); };

  return (
    <section className="flex min-h-0 flex-col" aria-label="Live asset previews" data-live-assets={buildId}>
      <div className="flex items-center gap-2 px-3 pt-2">
        <span className="font-cy-display text-[12.5px] font-semibold text-cy-ink">{done ? "Assets in this build" : replaying ? "Replaying the build" : "Assets, live"}</span>
        <span className="text-[11px] text-cy-muted">{state.order.length}</span>
        <span className="flex-1" />
        {!compact && !done && (
          <button type="button" aria-pressed={isPinned} onClick={() => pin(buildId, isPinned ? null : focusPath)} className="cy5-btn-ghost h-7 px-2 text-[11px]" title={isPinned ? "Follow whatever Cyrus is writing" : "Hold the preview on this asset"}>
            {isPinned ? "Pinned" : "Pin"}
          </button>
        )}
        {!compact && stored && (
          <button type="button" onClick={() => setReplaying((r) => !r)} className="cy5-btn-ghost h-7 px-2 text-[11px]">{replaying ? "Stop replay" : "Replay"}</button>
        )}
      </div>
      <div role="tablist" aria-label="Assets" className="flex gap-1 overflow-x-auto px-3 pt-1.5" style={{ scrollbarWidth: "none" }}>
        {state.order.map((p) => {
          const a = state.assets[p];
          const on = p === focusPath;
          return (
            <button key={p} type="button" role="tab" aria-selected={on} onClick={() => select(p)} title={`${KIND_LABEL[a.kind]} ${a.name}: ${STAGE_HINT[a.stage]}`}
              className={`flex shrink-0 items-center gap-1.5 rounded-lg px-2 py-1 text-[11.5px] transition ${on ? "bg-[rgb(var(--glow)/0.12)] text-cy-ink" : "text-cy-muted hover:text-cy-ink"}`}>
              <span aria-hidden className="text-[11px]">{KIND_GLYPH[a.kind]}</span>
              <span className="max-w-[110px] truncate">{a.name}</span>
              <span aria-hidden className={`h-1.5 w-1.5 rounded-full ${a.stage === "drafting" ? "cy-live-dot bg-cy-cyan" : a.stage === "built" ? "bg-cy-accent" : a.stage === "validated" ? "bg-[#10b981]" : a.stage === "dropped" ? "bg-[#f43f5e]" : a.stage === "problems" ? "bg-[#f59e0b]" : "bg-cy-faint"}`} />
            </button>
          );
        })}
      </div>
      {asset && (
        <div className="m-3 mt-2 flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl border border-cy-line bg-[rgb(var(--glow)/0.025)]">
          <div className="flex items-center gap-2 border-b border-cy-line px-3 py-1.5">
            <span className="text-[11px] text-cy-muted">{KIND_LABEL[asset.kind]}</span>
            <span className="truncate font-mono text-[11px] text-cy-ink-2">{asset.path || asset.name}</span>
            <span className="flex-1" />
            <StagePill stage={asset.stage} />
          </div>
          <div className={`min-h-0 flex-1 overflow-y-auto ${compact ? "max-h-[180px]" : ""}`} aria-live="polite" aria-busy={asset.stage === "drafting"}>
            {asset.truncated ? <div className="p-4 text-[12px] text-cy-muted">This spec is too large to preview live. It is still checked and built as usual.</div> : <FocusedPreview asset={asset} textures={textures} compact={compact} />}
          </div>
          {asset.info.length > 0 && <div className="border-t border-cy-line px-3 py-1.5 text-[11px] text-cy-muted">{asset.info[0]}</div>}
        </div>
      )}
      {done && !compact && <Gallery state={state} textures={textures} focus={focusPath} onPick={select} />}
      {!compact && <p className="px-3 pb-2 text-[10.5px] text-cy-faint">Previews are drawn from the specs Cyrus writes. “Built” means compiled and safety-scanned into the plugin; Test Flight on a real server is separate.</p>}
    </section>
  );
}

function FocusedPreview({ asset, textures, compact }: { asset: LiveAsset; textures: Record<string, TextureSpec>; compact?: boolean }) {
  const view = useView(asset);
  if (!view) return null;
  return <Preview asset={asset} view={view} textures={textures} compact={compact} />;
}

function Thumb({ asset, textures }: { asset: LiveAsset; textures: Record<string, TextureSpec> }) {
  if (asset.kind === "texture" && textures[asset.name]) return <TextureThumb spec={textures[asset.name]} size={36} />;
  return <span aria-hidden className="grid h-9 w-9 place-items-center rounded-lg bg-[rgb(var(--glow)/0.08)] text-[15px] text-cy-ink-2">{KIND_GLYPH[asset.kind]}</span>;
}

function Gallery({ state, textures, focus, onPick }: { state: LiveState; textures: Record<string, TextureSpec>; focus: string; onPick: (p: string) => void }) {
  return (
    <div className="grid grid-cols-2 gap-1.5 px-3 pb-2 sm:grid-cols-3" aria-label="Asset gallery">
      {state.order.map((p) => {
        const a = state.assets[p];
        return (
          <button key={p} type="button" onClick={() => onPick(p)} className={`flex items-center gap-2 rounded-xl border px-2 py-1.5 text-left ${p === focus ? "border-cy-accent" : "border-cy-line"}`}>
            <Thumb asset={a} textures={textures} />
            <span className="min-w-0 flex-1">
              <span className="block truncate text-[11.5px] text-cy-ink">{a.name}</span>
              <span className="block truncate text-[10px] text-cy-muted">{KIND_LABEL[a.kind]} · {STAGE_LABEL[a.stage]}</span>
            </span>
          </button>
        );
      })}
    </div>
  );
}

/** True when this build has live assets to show (the panel layout splits only then). */
export function useHasLiveAssets(buildId: string | undefined): boolean {
  return useLiveAssets((s) => !!buildId && (s.byBuild[buildId]?.order.length ?? 0) > 0);
}

