#!/usr/bin/env node
// Cyrus r48: a hand-written FAKE Claude CLI for the live-asset end-to-end (test/cyrus-liveassets-e2e.test.ts and the
// screenshot run). No model, nothing paid: it prints the CLI's stream-json the way the real one does with
// --include-partial-messages (content_block_start tool_use Write -> input_json_delta chunks -> content_block_stop ->
// assistant tool_use -> the tool runs -> user tool_result) for a scripted multi-asset build, writing each file for real.
//   env: LIVE_FAKE_ROOT (repo root, for the spec fixtures), LIVE_FAKE_DELAY_MS (per chunk, default 4),
//        LIVE_FAKE_CHUNK (chars per delta, default 160), HOME (claude.log)
"use strict";
const fs = require("fs");
const path = require("path");

const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "";
const ROOT = process.env.LIVE_FAKE_ROOT || path.resolve(__dirname, "../..");
const DELAY = Math.max(0, parseInt(process.env.LIVE_FAKE_DELAY_MS || "4", 10) || 0);
const CHUNK = Math.max(8, parseInt(process.env.LIVE_FAKE_CHUNK || "160", 10) || 160);
const ws = process.cwd();
const NS = (prompt.match(/reserved namespace is (nx_[a-z0-9]{8})/) || [])[1] || "nx_11ve0000";
const out = (o) => process.stdout.write(JSON.stringify(o) + "\n");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const read = (rel) => JSON.parse(fs.readFileSync(path.join(ROOT, rel), "utf8"));
try { fs.appendFileSync(path.join(process.env.HOME || "/tmp", "claude.log"), JSON.stringify({ live: /LIVEASSETS/.test(prompt), repair: !/Build this Paper/.test(prompt) }) + "\n"); } catch { /* log is optional */ }

function files() {
  const tex = read("services/modbuilder/texture-example.json");
  tex.name = "ember_blade";
  const snd = read("services/modbuilder/sound-example.json");
  const rig = read("test/fixtures/cyrus-liveassets/banshee-rig.json");
  const dp = read("services/modbuilder/datapack-example.json");
  const item = read("services/modbuilder/designer-example.json");
  const door = { schemaVersion: 1, kind: "motion", id: "vault_door", title: "Vault door", motion: { preset: "motion:door_hinge", params: {} }, minecraft: { triggers: { rightClick: "toggle" } } };
  const config = { schemaVersion: 1, groups: [{ id: "stats", label: "Stats" }], params: [
    { key: "blade.damage", group: "stats", type: "number", label: "Blade damage", default: 9, unit: "hp", min: 1, max: 40 },
    { key: "blade.cooldown", group: "stats", type: "duration", durationUnit: "ticks", label: "Ability cooldown", default: 160, min: 20, max: 1200 },
    { key: "banshee.spawn_chance", group: "stats", type: "number", label: "Banshee spawn chance", default: 0.05, min: 0, max: 1 },
    { key: "messages.enabled", group: "stats", type: "bool", label: "Show messages", default: true },
  ] };
  const keys = snd.events.map((e) => `"${NS}:${snd.name}.${e.event}"`).join(", ");
  return [
    ["src/main/resources/plugin.yml", `name: EmberBlade\nversion: 1.0.0\nmain: dev.nxeon.plugins.ember.EmberBlade\napi-version: '1.21'\ndescription: Ember blade\nauthor: Nxeon Mod Builder\n`],
    ["src/main/java/dev/nxeon/plugins/ember/EmberBlade.java", `package dev.nxeon.plugins.ember;\n\nimport org.bukkit.NamespacedKey;\nimport org.bukkit.plugin.java.JavaPlugin;\n\npublic class EmberBlade extends JavaPlugin {\n  static final NamespacedKey MODEL = new NamespacedKey("${NS}", "ember_blade");\n  static final String[] KEYS = { ${keys} };\n\n  @Override\n  public void onEnable() {\n    saveDefaultConfig();\n    getLogger().info("Ember Blade ready");\n  }\n}\n`],
    ["assets/textures/ember_blade.json", JSON.stringify(tex, null, 1)],
    ["assets/creatures/banshee.json", JSON.stringify(rig, null, 1)],
    ["assets/sounds/banshee.json", JSON.stringify(snd, null, 1)],
    ["assets/designs/vault_door.json", JSON.stringify(door, null, 1)],
    ["assets/designs/void_reaper.json", JSON.stringify(item, null, 1)],
    ["assets/config/schema.json", JSON.stringify(config, null, 1)],
    ["assets/datapack/glow_realm.json", JSON.stringify(dp, null, 1)],
    ["modbuilder.json", JSON.stringify({ name: "EmberBlade", version: "1.0.0", tagline: "An ember blade", summary: "Adds an ember blade.", howToUse: ["Hold it"] })],
  ];
}

async function writeTool(idx, rel, content) {
  const id = `toolu_live_${idx}`;
  const input = JSON.stringify({ file_path: path.join(ws, rel), content });
  out({ type: "stream_event", event: { type: "content_block_start", index: 1, content_block: { type: "tool_use", id, name: "Write", input: {} } } });
  for (let i = 0; i < input.length; i += CHUNK) {
    out({ type: "stream_event", event: { type: "content_block_delta", index: 1, delta: { type: "input_json_delta", partial_json: input.slice(i, i + CHUNK) } } });
    if (DELAY) await sleep(DELAY);
  }
  out({ type: "stream_event", event: { type: "content_block_stop", index: 1 } });
  out({ type: "assistant", message: { id: `m${idx}`, content: [{ type: "tool_use", id, name: "Write", input: { file_path: path.join(ws, rel), content } }] } });
  fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true });
  fs.writeFileSync(path.join(ws, rel), content);
  out({ type: "user", message: { content: [{ type: "tool_result", tool_use_id: id, content: "File written" }] } });
}

(async () => {
  out({ type: "system", subtype: "init", model: "claude-sonnet-5-5" });
