// Cyrus r48 live asset streaming: partial JSON, the service's path rules + ring/caps (services/modbuilder/liveassets.js),
// the portal's follow translation, event ordering in the live state, and the safe interpreters.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { parsePartialJson, PARTIAL_JSON_MAX_CHARS } from "../lib/cyrus/liveassets/partial-json";
import { applyLive, emptyLive, foldLive } from "../lib/cyrus/liveassets/state";
import { assetEvents, assetQuery, newAssetFollow } from "../lib/cyrus/liveassets/follow-assets";
import { configView, creatureView, designView, soundView, textureView, viewOf } from "../lib/cyrus/liveassets/interpret";
import { kindOfAssetPath, LIVE_MAX_ASSETS, type LiveAssetEvent } from "../lib/cyrus/liveassets/types";
import { liveAssetsOn } from "../lib/cyrus/liveassets/flags";
import { CYRUS_ENV_FLAGS } from "../lib/cyrus/admin/flags";

type LA = {
  ENABLED: (env?: Record<string, string | undefined>) => boolean; MAX_SPEC_BYTES: number; MAX_EVENTS: number; MAX_STORED_BYTES: number;
  kindOfPath: (p: string) => string | null; assetRel: (ws: string, fp: string) => { rel: string; kind: string } | null;
  newLog: () => { seq: number; events: { seq: number; type: string; content?: string }[] };
  push: (l: unknown, e: Record<string, unknown>) => unknown; complete: (l: unknown, rel: string, kind: string, content: string, op: string) => { truncated?: boolean; content?: string };
  verdicts: (l: unknown, kind: string, results: unknown[], o?: { final?: boolean }) => void; built: (l: unknown, shipped: unknown[]) => void;
  picks: (l: unknown, slots: unknown[], pool: unknown[]) => void;
  since: (l: unknown, after: number) => { seq: number; events: { seq: number; type: string }[]; gap: boolean };
  stored: (l: unknown) => { events: { content?: string }[] };
  draftOf: (ws: string, d: unknown, pf: unknown, want: string, wantSeq: number, wantFrom: number) => Record<string, unknown> | null;
};
// eslint-disable-next-line @typescript-eslint/no-require-imports
const L = require("../services/modbuilder/liveassets.js") as LA;
// eslint-disable-next-line @typescript-eslint/no-require-imports
const { partialField } = require("../services/modbuilder/live.js") as { partialField: unknown };
const ROOT = path.resolve(__dirname, "..");
const TEX = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/texture-example.json"), "utf8"));

describe("partial JSON reader", () => {
  it("every prefix parses without throwing; the stable part only grows; the whole text = JSON.parse", () => {
    const text = JSON.stringify(TEX, null, 1);
    let lastOps = 0;
    for (let i = 0; i <= text.length; i++) {
      const p = parsePartialJson(text.slice(0, i));
      assert.equal(p.error, null, `prefix ${i}`);
      const ops = (p.value as { ops?: unknown[] } | undefined)?.ops?.length ?? 0;
      assert.ok(ops >= lastOps, `ops never shrink (prefix ${i})`);
      lastOps = ops;
    }
    const full = parsePartialJson(text);
    assert.equal(full.complete, true);
    assert.deepEqual(full.value, TEX);
  });
  it("unfinished members wait: half strings/numbers/objects are left out (half strings kept on request)", () => {
    assert.deepEqual(parsePartialJson('{"a":1,"b":"hal').value, { a: 1 });
    assert.deepEqual(parsePartialJson('{"a":1,"b":"hal', { partialStrings: true }).value, { a: 1, b: "hal" });
    assert.deepEqual(parsePartialJson('{"n":12').value, {}, "a number at the end may still grow");
    assert.deepEqual(parsePartialJson('{"ops":[{"op":"px","x":1},{"op":"re').value, { ops: [{ op: "px", x: 1 }] });
    assert.deepEqual(parsePartialJson('{"t":tr').value, {});
    assert.equal(parsePartialJson('{"a":1}').complete, true);
  });
  it("caps: too deep, too large, prototype keys, garbage", () => {
    assert.equal(parsePartialJson("[".repeat(40)).error, "too deep");
    assert.equal(parsePartialJson(" ".repeat(PARTIAL_JSON_MAX_CHARS + 1)).error, "too large");
    const p = parsePartialJson('{"__proto__":{"x":1},"constructor":1,"ok":2}');
    assert.deepEqual(p.value, { ok: 2 });
    assert.equal(({} as { x?: number }).x, undefined);
    assert.ok(parsePartialJson("{]").error);
    assert.ok(parsePartialJson('{"a":tru3}').error);
  });
});

describe("service: path rules, ring, caps (liveassets.js)", () => {
  it("only asset spec paths; never code, secrets, traversal or other folders", () => {
    for (const [p, k] of [["assets/textures/ruby.json", "texture"], ["assets/sounds/banshee.json", "sound"], ["assets/designs/void_reaper.json", "design"], ["assets/creatures/golem.json", "creature"], ["assets/datapack/realm.json", "datapack"], ["assets/itemmodels/bow.json", "itemmodel"], ["assets/config/schema.json", "config"], ["assets/library.json", "library"]]) assert.equal(L.kindOfPath(p), k, p);
    for (const p of ["src/main/java/A.java", "src/main/resources/plugin.yml", "assets/textures/../x.json", "assets/textures/Ruby.json", ".credentials.json", "assets/textures/a.png", "reference/a.json", "assets/config/other.json", "/etc/passwd"]) assert.equal(L.kindOfPath(p), null, p);
    assert.deepEqual(L.assetRel("/w/b1", "/w/b1/assets/sounds/s1.json"), { rel: "assets/sounds/s1.json", kind: "sound" });
    assert.equal(L.assetRel("/w/b1", "/w/b2/assets/sounds/s1.json"), null);
    assert.equal(L.assetRel("/w/b1", "/w/b1/../b2/assets/sounds/s1.json"), null);
    for (const p of ["assets/textures/a.json", "assets/library.json"]) assert.equal(kindOfAssetPath(p) !== null, true, "portal rules = service rules");
    assert.equal(kindOfAssetPath("src/main/java/A.java"), null);
  });
  it("off unless CYRUS_LIVE_ASSETS=1 (service and portal); listed in the admin flags", () => {
    assert.equal(L.ENABLED({}), false); assert.equal(L.ENABLED({ CYRUS_LIVE_ASSETS: "1" }), true); assert.equal(L.ENABLED({ CYRUS_LIVE_ASSETS: "true" }), false);
    assert.equal(liveAssetsOn({}), false); assert.equal(liveAssetsOn({ CYRUS_LIVE_ASSETS: "1" }), true);
    assert.ok(CYRUS_ENV_FLAGS.some((f) => f.key === "CYRUS_LIVE_ASSETS"));
  });
  it("ring keeps the newest MAX_EVENTS, seq strictly increases, since() pages and flags a gap", () => {
    const log = L.newLog();
    for (let i = 0; i < L.MAX_EVENTS + 30; i++) L.push(log, { type: "validated", kind: "texture", path: "assets/textures/a.json" });
    assert.equal(log.events.length, L.MAX_EVENTS);
    assert.ok(log.events.every((e, i) => i === 0 || e.seq === log.events[i - 1].seq + 1));
    const s = L.since(log, 0);
    assert.equal(s.gap, true, "events 1..30 fell out of the ring");
    assert.ok(s.events.length <= 80);
    const tail = L.since(log, log.seq - 5);
    assert.equal(tail.events.length, 5); assert.equal(tail.gap, false);
  });
  it("complete: over the size cap = no content; stored timeline stays under its byte cap", () => {
    const log = L.newLog();
    assert.equal(L.complete(log, "assets/textures/a.json", "texture", "x".repeat(L.MAX_SPEC_BYTES + 1), "write").truncated, true);
    for (let i = 0; i < 20; i++) L.complete(log, "assets/sounds/s.json", "sound", "y".repeat(40_000), "write");
    const st = L.stored(log);
    assert.ok(Buffer.byteLength(JSON.stringify(st.events)) <= L.MAX_STORED_BYTES);
    assert.ok(st.events.length > 0);
  });
  it("verdicts, picks and built: problems vs dropped, library titles from the gated pool, built for shipped specs", () => {
    const log = L.newLog();
    L.verdicts(log, "texture", [{ rel: "assets/textures/a.json", name: "a", ok: true }, { rel: "assets/textures/b.json", name: "b", ok: false, problems: ["bad colour"] }, { rel: "src/main/java/X.java", ok: true }]);
    L.verdicts(log, "texture", [{ rel: "assets/textures/b.json", name: "b", ok: false, problems: ["bad colour"] }], { final: true });
    L.picks(log, [{ id: "door_creak", kind: "sound", purpose: "door opening", libraryRef: "cat:" + "a".repeat(64) }], [{ ref: "cat:" + "a".repeat(64), row: { title: "Old door creak" } }]);
    L.built(log, [{ path: "assets/textures/a.json", name: "a" }, { path: "src/x", name: "x" }]);
    const t = L.since(log, 0).events.map((e) => `${e.type}:${(e as unknown as { path: string }).path}`);
    assert.deepEqual(t, ["validated:assets/textures/a.json", "problems:assets/textures/b.json", "dropped:assets/textures/b.json", "validated:assets/library.json", "built:assets/textures/a.json", "built:"]);
    assert.equal((L.since(log, 3).events[0] as unknown as { picks: { title: string }[] }).picks[0].title, "Old door creak");
  });
  it("draftOf: Writes stream after `from` (same path + seq), Edits only announce, code drafts are not assets", () => {
    const json = JSON.stringify({ file_path: "/w/b1/assets/textures/ember.json", content: '{"name":"ember","size":16' });
    const d = L.draftOf("/w/b1", { tool: "Write", json, seq: 3 }, partialField, "", 0, 0)!;
    assert.equal(d.kind, "texture"); assert.equal(d.from, 0); assert.equal(d.text, '{"name":"ember","size":16');
    const d2 = L.draftOf("/w/b1", { tool: "Write", json, seq: 3 }, partialField, "assets/textures/ember.json", 3, 10)!;
    assert.equal(d2.from, 10); assert.equal(d2.text, '{"name":"ember","size":16'.slice(10));
    assert.equal(L.draftOf("/w/b1", { tool: "Write", json, seq: 4 }, partialField, "assets/textures/ember.json", 3, 10)!.from, 0, "another tool call starts over");
    assert.equal(L.draftOf("/w/b1", { tool: "Edit", json, seq: 3 }, partialField, "", 0, 0)!.text, "");
    assert.equal(L.draftOf("/w/b1", { tool: "Write", json: JSON.stringify({ file_path: "/w/b1/src/main/java/A.java", content: "class A" }), seq: 1 }, partialField, "", 0, 0), null);
    assert.equal(L.draftOf("/w/b1", { tool: "Write", json: JSON.stringify({ file_path: "/w/b2/assets/textures/a.json", content: "{}" }), seq: 1 }, partialField, "", 0, 0), null);
  });
});

