    const dz = viewOf(state.assets["assets/designs/void_reaper.json"]) as { abilities: unknown[] };
    assert.ok(dz.abilities.length >= 2);
    const door = viewOf(state.assets["assets/designs/vault_door.json"]) as { motion: { spec: unknown; lanes: unknown[] } };
    assert.ok(door.motion.spec && door.motion.lanes.length > 0, "the preset simulates once complete");
  });
