    const st = (await get(svc, "/builds/live-e2e-01/live?assets=1&aseq=0")) as SvcLive;
    assert.equal(st.live, false); assert.equal(st.assets?.stored, true);
    const f = newAssetFollow();
    const evs: LiveAssetEvent[] = [];
    for (let k = 0; k < 4; k++) { const got = assetEvents(f, st.assets); evs.push(...got); if (got.length < 80) break; }
    const re = foldLive(evs);
    for (const p of state.order) assert.equal(re.assets[p]?.stage, state.assets[p].stage, p);
  });
  it("with CYRUS_LIVE_ASSETS off the service records nothing and ignores assets=1", async () => {
    const off = await start(false, 0);
    await post(off, "/builds", { id: "live-off-01", ...BUILD });
    let sawAssets = false;
    for (let i = 0; i < 400; i++) {
      const l = await get(off, "/builds/live-off-01/live?assets=1&aseq=0");
      if ("assets" in l) sawAssets = true;
      const r = await get(off, "/builds/live-off-01");
      if (r.status === "succeeded" || r.status === "failed") break;
      await new Promise((res) => setTimeout(res, 25));
    }
    assert.equal(sawAssets, false);
    assert.equal(fs.existsSync(path.join(off.dir, "data", "builds", "live-off-01", "live-assets.json")), false);
  });
});

