      const qs = `assets=1&aseq=${q.aseq}${q.adraft ? `&adraft=${encodeURIComponent(q.adraft)}&aseqd=${q.aseqd}&afrom=${q.afrom}` : ""}`;
      const live = (await get(svc, `/builds/live-e2e-01/live?${qs}`)) as SvcLive;
      if (i % 10 === 0) plainKeys.push(Object.keys(await get(svc, "/builds/live-e2e-01/live")));
      for (const ev of assetEvents(f, live.assets)) {
        recorded.push({ t: Date.now() - t0, ev });
        state = applyLive(state, ev);
        const a = state.assets[ev.path];
        if (ev.type === "partial" && a && a.text.length > 200 && !midViews[a.kind + ":" + a.path]) midViews[a.kind + ":" + a.path] = viewOf(a);
      }
      const r = await get(svc, "/builds/live-e2e-01");
      if ((r.status === "succeeded" || r.status === "failed") && !live.live) { final = r; break; }
      await new Promise((res) => setTimeout(res, 20));
    }
    // the stored tail (what follow.ts reads after the build)
    const tail = (await get(svc, `/builds/live-e2e-01/live?assets=1&aseq=${f.aseq}`)) as SvcLive;
    for (const ev of assetEvents(f, tail.assets)) { recorded.push({ t: Date.now() - t0, ev }); state = applyLive(state, ev); }
    if (process.env.LIVE_RECORD) fs.writeFileSync(process.env.LIVE_RECORD, JSON.stringify({ events: recorded }));
  });
  after(() => { for (const s of svcs) { s.proc.kill("SIGKILL"); fs.rmSync(s.dir, { recursive: true, force: true }); } });

  it("the build succeeds as usual", () => {
    assert.equal(final.status, "succeeded", JSON.stringify((final.events as { message: string }[] | undefined)?.map((e) => e.message)) + svc.err.slice(-1500));
  });
  it("every asset kind streams as a draft before it is finished, then lands as complete with the file content", () => {
    const paths = ["assets/textures/ember_blade.json", "assets/creatures/banshee.json", "assets/sounds/banshee.json", "assets/designs/vault_door.json", "assets/designs/void_reaper.json", "assets/config/schema.json", "assets/datapack/glow_realm.json"];
    for (const p of paths) {
      const evs = recorded.filter((r) => r.ev.path === p).map((r) => r.ev);
      const firstPartial = evs.findIndex((e) => e.type === "partial");
      const complete = evs.findIndex((e) => e.type === "complete");
      assert.ok(firstPartial >= 0, `${p}: drafted live`);
      assert.ok(complete > firstPartial, `${p}: complete after its drafts`);
      const c = evs[complete] as { content?: string };
      assert.ok(c.content && JSON.parse(c.content), `${p}: complete carries the spec`);
      assert.equal(state.assets[p].text, c.content);
    }
  });
  it("mid-stream views per kind: texture strokes, model cubes, sound events, design graph, settings fill in progressively", () => {
    const pick = (k: string) => Object.entries(midViews).find(([key]) => key.startsWith(k + ":"))?.[1] as Record<string, unknown> | undefined;
    const tex = pick("texture") as { spec?: { ops: unknown[] } | null } | undefined;
    const done = viewOf(state.assets["assets/textures/ember_blade.json"]) as { spec?: { ops: unknown[] } | null };
    assert.ok(done.spec && (!tex?.spec || tex.spec.ops.length <= done.spec.ops.length));
    const cr = viewOf(state.assets["assets/creatures/banshee.json"]) as { cubes: unknown[]; ok: boolean | null };
    assert.ok(cr.cubes.length > 5); assert.equal(cr.ok, true);
    const midCr = pick("creature") as { cubes: unknown[] } | undefined;
    assert.ok(!midCr || midCr.cubes.length < cr.cubes.length, "cubes appear as they arrive");
    const dz = viewOf(state.assets["assets/designs/void_reaper.json"]) as { abilities: unknown[] };
    assert.ok(dz.abilities.length >= 2);
    const door = viewOf(state.assets["assets/designs/vault_door.json"]) as { motion: { spec: unknown; lanes: unknown[] } };
    assert.ok(door.motion.spec && door.motion.lanes.length > 0, "the preset simulates once complete");
  });
  it("validator verdicts then built; dropped/unchecked kinds stay honest", () => {
    const stage = (p: string) => state.assets[p].stage;
    assert.equal(stage("assets/textures/ember_blade.json"), "built");
    assert.equal(stage("assets/sounds/banshee.json"), "built");
    assert.ok(["built", "dropped"].includes(stage("assets/datapack/glow_realm.json")), stage("assets/datapack/glow_realm.json"));
    for (const p of ["assets/creatures/banshee.json", "assets/designs/void_reaper.json", "assets/config/schema.json"]) assert.equal(stage(p), "written", `${p}: route off in this build, never claimed validated`);
    assert.equal(state.built, true);
    const order = (p: string, t: string) => recorded.findIndex((r) => r.ev.path === p && r.ev.type === t);
    assert.ok(order("assets/textures/ember_blade.json", "complete") < order("assets/textures/ember_blade.json", "validated"));
    assert.ok(order("assets/textures/ember_blade.json", "validated") < order("assets/textures/ember_blade.json", "built"));
  });
  it("never sends code or anything outside the asset folders; seq strictly increases; bounded", () => {
    for (const r of recorded) assert.ok(r.ev.path === "" || /^assets\//.test(r.ev.path), r.ev.path);
    const seqs = recorded.filter((r) => r.ev.type !== "partial").map((r) => r.ev.seq);
    assert.ok(seqs.every((s, i) => i === 0 || s > seqs[i - 1]));
    assert.ok(!JSON.stringify(recorded).includes("public class EmberBlade"), "Java never rides the asset channel");
    for (const r of recorded) if (r.ev.type === "partial") assert.ok(r.ev.text.length <= 64 * 1024);
  });
  it("/live without assets=1 answers exactly as before", () => {
    assert.ok(plainKeys.length > 0);
    for (const k of plainKeys) assert.deepEqual(k.sort(), ["draft", "files", "live", "status"]);
  });
  it("the stored timeline replays to the same final stages", async () => {
    const st = (await get(svc, "/builds/live-e2e-01/live?assets=1&aseq=0")) as SvcLive;
    assert.equal(st.live, false); assert.equal(st.assets?.stored, true);
    const f = newAssetFollow();
    const evs: LiveAssetEvent[] = [];
    for (let k = 0; k < 4; k++) { const got = assetEvents(f, st.assets); evs.push(...got); if (got.length < 80) break; }
    const re = foldLive(evs);
    for (const p of state.order) assert.equal(re.assets[p]?.stage, state.assets[p].stage, p);
  });
  it("with CYRUS_LIVE_ASSETS off the service records nothing and ignores assets=1", async () => {
    const off = await start(false, 0);
    await post(off, "/builds", { id: "live-off-01", ...BUILD });
    let sawAssets = false;
    for (let i = 0; i < 400; i++) {
      const l = await get(off, "/builds/live-off-01/live?assets=1&aseq=0");
      if ("assets" in l) sawAssets = true;
      const r = await get(off, "/builds/live-off-01");
      if (r.status === "succeeded" || r.status === "failed") break;
      await new Promise((res) => setTimeout(res, 25));
    }
    assert.equal(sawAssets, false);
    assert.equal(fs.existsSync(path.join(off.dir, "data", "builds", "live-off-01", "live-assets.json")), false);
  });
});

