// Cyrus r48 live asset screenshots (run ON node-2 against `devhost dev` after scripts/cyrus/studio-fixtures.ts). Not part
// of the app. Replays a stream RECORDED from the real build service + fake CLI (test/cyrus-liveassets-e2e.test.ts with
// LIVE_RECORD=<file>) into the real build screen through the dev-only hook (lib/cyrus/liveassets/dev-hook.ts), and
// shoots a mid-stream frame per asset kind plus the finished gallery, dark desktop + phone.
//   devhost run -- env BASE=http://127.0.0.1:<port> TOKENS=.studio-tokens.json REC=<record.json> OUT=<dir> node scripts/cyrus/liveassets-shots.mjs
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:3000";
const OUT = process.env.OUT ?? ".shots/live";
const tok = JSON.parse(readFileSync(process.env.TOKENS ?? ".studio-tokens.json", "utf8"));
const rec = JSON.parse(readFileSync(process.env.REC, "utf8")).events.map((r) => r.ev);
mkdirSync(OUT, { recursive: true });
const ONLY = process.env.SHOTS ? process.env.SHOTS.split(",") : null;
const VIEW = { desktop: { width: 1440, height: 900, mobile: false }, phone: { width: 390, height: 844, mobile: true } };
const JAVA = readFileSync(new URL("./live-assets-fake-cli.js", import.meta.url), "utf8").includes("EmberBlade")
  ? 'package dev.nxeon.plugins.ember;\n\nimport org.bukkit.NamespacedKey;\nimport org.bukkit.plugin.java.JavaPlugin;\n\npublic class EmberBlade extends JavaPlugin {\n  static final NamespacedKey MODEL = new NamespacedKey("nx_11ve0a55", "ember_blade");\n\n  @Override\n  public void onEnable() {\n    saveDefaultConfig();\n    getLogger().info("Ember Blade ready");\n  }\n}\n'
  : "";

// index of the event at which `path`'s draft is about `frac` written
function midIndex(path, frac) {
  const total = (rec.find((e) => e.type === "complete" && e.path === path)?.content ?? "").length;
  let len = 0;
  for (let i = 0; i < rec.length; i++) {
    const e = rec[i];
    if (e.type === "partial" && e.path === path) { len = e.from + e.text.length; if (total && len >= total * frac) return i; }
    if (e.type === "complete" && e.path === path) return i;
  }
  return -1;
}
const browser = await chromium.launch();
async function session(view, theme = "dark") {
  const v = VIEW[view];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: v.mobile ? 2 : 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: tok.cookie, value: tok.all.token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + "/dashboard/cyrus", { waitUntil: "load", timeout: 300000 });
  await page.waitForFunction(() => window.__cyrusLiveDev && window.__cyrusLiveDev.studio.getState().realBuilds.length > 0, null, { timeout: 240000 }).catch(() => {});
  // the panel module (with the hook) loads lazily: open the real mod first
  const info = await page.evaluate(() => {
    const s = window.__cyrusLiveDev?.studio.getState();
    const b = s?.realBuilds.find((x) => !x.rootBuildId) ?? s?.realBuilds[0];
    return b ? { root: b.rootBuildId ?? b.id, buildId: b.id } : null;
  });
  return { ctx, page, errs, info, view };
}
async function openMod(s, wide) {
  if (!s.info) { await s.page.goto(BASE + "/dashboard/cyrus", { waitUntil: "load" }); }
  const modId = s.info ? "nx-" + s.info.root : null;
  if (modId) await s.page.goto(BASE + "/dashboard/cyrus/" + modId, { waitUntil: "load", timeout: 300000 });
  await s.page.waitForFunction(() => !!window.__cyrusLiveDev, null, { timeout: 240000 });
  await s.page.evaluate(([modId, wide]) => {
    const st = window.__cyrusLiveDev.studio;
    const sel = st.getState().select;
    if (modId && sel) sel({ level: "mod", gameId: "minecraft", modId }, { openPanel: true });
    st.setState({ panelTab: "code", panelWide: wide });
  }, [modId, wide]);
  await s.page.waitForTimeout(1500);
  return modId;
}
async function stream(s, modId, upTo, live = true) {
  await s.page.evaluate(([modId, evs, java, live, buildId]) => {
    const { studio, live: la } = window.__cyrusLiveDev;
    const id = buildId;
    const now = Date.now();
